1	/**
2	 * MCP HTTP Handler v2
3	 * 
4	 * Slim orchestration layer that composes the decomposed modules:
5	 * - tool-registry.ts  → tool definitions, schemas, categories
6	 * - tool-executor.ts  → dispatch table, tool execution
7	 * - mcp-auth.ts       → API key extraction, validation, middleware
8	 * - mcp-usage.ts      → usage logging, governance events, token estimation
9	 * 
10	 * This file handles only HTTP routing and JSON-RPC protocol concerns.
11	 * 
12	 * HARDENED: Per-request timeout protection with graceful degradation.
13	 * If a tool call exceeds the timeout, a partial/timeout response is returned
14	 * instead of hanging until the transport layer drops the connection (503/EOF).
15	 */
16	
17	import { Router, Request, Response } from 'express';
18	import { z, ZodTypeAny } from 'zod';
19	import { createLogger } from '../_core/logger';
20	import { initGravitoMCPServer, GRAVITO_MCP_SERVER_NAME } from '../agent/mcp/gravito-mcp-server';
21	import { ALL_TOOLS, BRIDGE_TOOL_SCHEMAS } from './tool-registry';
22	import { executeTool } from './tool-executor';
23	import { filterActiveTools } from './tool-self-governance';
24	import { authenticateMCP, extractApiKey, validateApiKey, AUTH_METADATA } from './mcp-auth';
25	import {
26	  logUsage,
27	  getUsageStats,
28	  emitGovernanceEvent,
29	  estimateTokens,
30	  isBlockedResponse,
31	  extractScore,
32	} from './mcp-usage';
33	import { recordToolExecution, shouldUseFallbackMode } from './mcp-health-probe';
34	import { checkRateLimit, getRateLimitStatus } from './mcp-rate-limiter';
35	import { recordAudit } from './mcp-audit-trail';
36	import {
37	  shouldUseAsync, createAsyncJob, markRunning, completeAsyncJob,
38	  failAsyncJob, getJob, buildJobResponse, getAsyncQueueStats,
39	  listJobs, cancelJob, getEstimatedDuration, JobStatus,
40	} from './async-job-queue';
41	import {
42	  extractCorrelationId, buildCorrelationContext, getCorrelationHeaders,
43	  enrichMCPResponse, classify503Cause, build503Response,
44	  classifyGovernanceRequirement, waitForJobCompletion,
45	} from './nervous-system-stabilizer';
46	import { enforceGate, buildGovernanceEnvelope, type GateEnforcementResult } from './gate-enforcement';
47	import type { Surface } from './fail-closed-gate';
48	import { isFeatureEnabled } from '../emotional-geometry-runtime/feature-flags';
49	import { resolveGovernedAuthenticatedTenant } from '../governance/governed-authenticated-tenant';
50	
51	const generalLog = createLogger('mcp');
52	
53	// ============================================================================
54	// TIMEOUT CONFIGURATION
55	// ============================================================================
56	
