116	const DEFAULT_TOOL_TIMEOUT_MS = 30_000;
117	const SLOW_TOOL_TIMEOUT_MS = 55_000;
118	
119	function getToolTimeout(toolName: string): number {
120	  return SLOW_TOOLS.has(toolName) ? SLOW_TOOL_TIMEOUT_MS : DEFAULT_TOOL_TIMEOUT_MS;
121	}
122	
123	async function withTimeout<T>(
124	  promise: Promise<T>,
125	  timeoutMs: number,
126	  _label: string,
127	): Promise<{ result: T; timedOut: false } | { timedOut: true; durationMs: number }> {
128	  const start = Date.now();
129	  return Promise.race([
130	    promise.then(result => ({ result, timedOut: false as const })),
131	    new Promise<{ timedOut: true; durationMs: number }>((resolve) =>
132	      setTimeout(() => resolve({ timedOut: true, durationMs: Date.now() - start }), timeoutMs)
133	    ),
134	  ]);
135	}
136	
137	// ============================================================================
138	// SERVER INITIALIZATION
139	// ============================================================================
140	
141	let serverInitialized = false;
142	
143	function ensureServerInitialized(): void {
144	  if (!serverInitialized) {
145	    initGravitoMCPServer();
146	    serverInitialized = true;
147	  }
148	}
149	
150	// ============================================================================
151	// INPUT NORMALIZER
152	// ============================================================================
153	
154	import { normalizeSchemaParams } from './schema-normalizer';
155	
156	function normalizeArgs(args: Record<string, unknown> | undefined, toolName?: string): Record<string, unknown> {
157	  if (!args) return {};
158	  let normalized = { ...args };
159	  if (normalized.arguments && typeof normalized.arguments === 'object' && !normalized.content) {
160	    Object.assign(normalized, normalized.arguments);
161	    delete normalized.arguments;
162	  }
163	  // Bridge camelCase↔snake_case parameter names to match Zod schema
164	  if (toolName) {
165	    normalized = normalizeSchemaParams(toolName, normalized);
166	  }
167	  return normalized;
168	}
169	
170	// ============================================================================
171	// ZOD → JSON SCHEMA CONVERTER
172	// ============================================================================
173	
174	function zodToJsonSchema(schema: z.ZodType<unknown>): Record<string, unknown> {
175	  const description = (schema as z.ZodType<unknown> & { description?: string }).description || '';
176	  const def = (schema as z.ZodType<unknown> & { _def: Record<string, unknown> })._def;
177	
178	  if (def?.typeName === 'ZodEnum') {
179	    return { type: 'string', enum: def.values || Object.keys(def.entries || {}), description };
180	  }
181	  if (def?.typeName === 'ZodNativeEnum') {
182	    return { type: 'string', enum: Object.values(def.values as Record<string, string>), description };
183	  }
184	  if (def?.type === 'enum' && def?.entries) {
185	    return { type: 'string', enum: Object.keys(def.entries), description };
186	  }
187	  if (schema instanceof z.ZodObject) {
188	    const shape = schema.shape;
189	    const properties: Record<string, Record<string, unknown>> = {};
190	    const required: string[] = [];
191	    for (const [key, value] of Object.entries(shape)) {
192	      properties[key] = zodToJsonSchema(value as z.ZodType<unknown>);
193	      if (!(value as z.ZodType<unknown> & { isOptional?: () => boolean }).isOptional?.()) required.push(key);
194	    }
195	    return { type: 'object', properties, required: required.length > 0 ? required : undefined, description };
196	  }
197	  if (schema instanceof z.ZodString) return { type: 'string', description };
198	  if (schema instanceof z.ZodNumber) return { type: 'number', description };
199	  if (schema instanceof z.ZodBoolean) return { type: 'boolean', description };
200	  if (schema instanceof z.ZodArray) {
201	    return { type: 'array', items: zodToJsonSchema((schema as z.ZodArray<ZodTypeAny>)._def.type), description };
202	  }
203	  if (schema instanceof z.ZodEnum) {
204	    return { type: 'string', enum: (schema as z.ZodEnum<[string, ...string[]]>)._def.values, description };
205	  }
206	  if (schema instanceof z.ZodDefault) {
207	    const inner = zodToJsonSchema((schema as z.ZodDefault<ZodTypeAny>)._def.innerType);
208	    try {
209	      const defaultVal = (schema as z.ZodType<unknown> & { _def: { defaultValue: unknown } })._def.defaultValue;
210	      inner.default = typeof defaultVal === 'function' ? defaultVal() : defaultVal;
211	    } catch { /* ignore */ }
212	    return inner;
213	  }
214	  if (schema instanceof z.ZodOptional) {
215	    return zodToJsonSchema((schema as z.ZodOptional<ZodTypeAny>)._def.innerType);
216	  }
217	  return { type: 'string', description };
218	}
219	
220	// ============================================================================
221	// ROUTER
222	// ============================================================================
223	
224	const mcpRouterV2 = Router();
225	
226	// ============================================================================
227	// JSON-RPC HANDLER
228	// Split: initialize + tools/list are unauthenticated (MCP spec: auth is OPTIONAL)
229	//        tools/call requires API key authentication
230	// This enables MCP CLI discovery without OAuth while protecting tool execution.
231	// ============================================================================
232	
233	interface EnrichedResult {
234	    content: { type: string; text: string }[];
235	}
236	
237	mcpRouterV2.post('/', async (req: Request, res: Response) => {
238	  const requestStart = Date.now();
239	  const clientIp = req.ip || req.socket.remoteAddress || 'unknown';
240	  const userAgent = req.headers['user-agent'] || 'unknown';
241	  const requestId = `mcp-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
242	  const correlationId = extractCorrelationId(req);
243	  res.setHeader('x-correlation-id', correlationId);
244	  res.setHeader('x-gravito-request-id', requestId);
245	
246	  try {
247	    ensureServerInitialized();
248	
249	    const { method, params, id } = req.body || {};
250	
251	    // Structured observability log for every MCP request
252	    generalLog.info(`[MCP] ${requestId} method=${method || 'unknown'} ip=${clientIp} ua=${userAgent.slice(0, 60)} hasAuth=${!!req.headers.authorization || !!req.headers['x-api-key']}`);
253	
254	    // ── READ-ONLY METHODS (no auth required) ──
255	    // Per MCP spec, initialize and tools/list are discovery operations.
256	    // Allowing them unauthenticated enables CLI tool listing and server discovery.
257	    switch (method) {
258	      case 'initialize':
259	        generalLog.info(`[MCP] ${requestId} initialize completed in ${Date.now() - requestStart}ms`);
260	        return res.json({
261	          jsonrpc: '2.0', id,
262	          result: {
263	            protocolVersion: '2024-11-05',
264	            capabilities: { tools: { listChanged: false } },
265	            serverInfo: { name: GRAVITO_MCP_SERVER_NAME, version: '1.0.0' },
266	          },
267	        });
268	
269	      case 'tools/list': {
270	        const activeTools = filterActiveTools(ALL_TOOLS);
271	        const toolsList = activeTools.map(tool => {
272	              const schema = tool.inputSchema as unknown as Record<string, unknown>;
273	              const isZod = (s: unknown): s is z.ZodTypeAny => !!s && typeof (s as z.ZodTypeAny).parse === 'function';
274	              return { name: tool.name, description: tool.description, inputSchema: isZod(schema) ? zodToJsonSchema(schema) : schema };
275	        });
276	        generalLog.info(`[MCP] ${requestId} tools/list returned ${toolsList.length} tools (${ALL_TOOLS.length - activeTools.length} quarantined) in ${Date.now() - requestStart}ms`);
277	        return res.json({
278	          jsonrpc: '2.0', id,
279	          result: { tools: toolsList },
280	        });
281	      }
282	
283	      case 'notifications/initialized':
284	        // MCP protocol notification — client confirms initialization complete
285	        generalLog.info(`[MCP] ${requestId} notifications/initialized ack in ${Date.now() - requestStart}ms`);
286	        return res.json({ jsonrpc: '2.0', id, result: {} });
287	
288	      case 'tools/call': {
289	        // ── AUTHENTICATED: tools/call requires API key ──
290	        const apiKey = extractApiKey(req);
291	        const hasServerKey =
292	          !!process.env.BUILT_IN_FORGE_API_KEY?.trim() ||
293	          !!process.env.GRAVITO_API_KEY?.trim() ||
294	          !!process.env.GravitoAPI?.trim();
295	        if (process.env.NODE_ENV !== 'development' || hasServerKey) {
296	          if (!apiKey) {
297	            return res.status(401).json({
298	              jsonrpc: '2.0', id,
299	              error: { code: -32000, message: 'Authentication required for tools/call. Provide API key via Authorization: Bearer <key> header or X-API-Key header.' },
300	            });
301	          }
302	
303	          const isValid = await validateApiKey(apiKey);
304	          if (!isValid) {
305	            return res.status(403).json({
306	              jsonrpc: '2.0', id,
307	              error: { code: -32001, message: 'Invalid API key provided.' },
308	            });
309	          }
310	        }
311	
312	        // MCP protocol uses 'arguments', but some clients send 'args' — support both
313	        const { name, arguments: mcpArguments, args: mcpArgs, webhook } = params || {};
314	        const rawArgs = mcpArguments || mcpArgs || {};
315	        const normalizedArgs = normalizeArgs(rawArgs, name);
316	
317	        if (!name || typeof name !== 'string') {
318	          return res.status(400).json({ jsonrpc: '2.0', id, error: { code: -32602, message: 'Invalid params: "name" is a required string.' } });
319	        }
320	
321	        const tool = ALL_TOOLS.find(t => t.name === name);
322	        if (!tool) {
323	          return res.status(404).json({ jsonrpc: '2.0', id, error: { code: -32601, message: `Tool not found: ${name}` } });
324	        }
325	
326	        // ── RATE LIMITING ──
327	        // FIX: checkRateLimit takes (apiKey, clientIp, toolName, method?)
328	        // FIX: RateLimitResult uses 'allowed' not 'success', 'retryAfterMs' not 'retryAfter', no 'reset' field
329	        const rateLimitResult = checkRateLimit(apiKey || 'anonymous', clientIp, name);
330	        res.setHeader('X-RateLimit-Limit', String(rateLimitResult.limit));
331	        res.setHeader('X-RateLimit-Remaining', String(rateLimitResult.remaining));
332	        // No 'reset' field in RateLimitResult — use estimated retry time
333	        res.setHeader('X-RateLimit-Reset', String(Math.ceil(Date.now() / 1000) + 60));
334	
335	        if (!rateLimitResult.allowed) {
336	          const retryAfterSec = Math.ceil((rateLimitResult.retryAfterMs || 5000) / 1000);
337	          res.setHeader('Retry-After', String(retryAfterSec));
338	          return res.status(429).json({
339	            jsonrpc: '2.0', id,
340	            error: {
341	              code: -32005,
342	              message: `Rate limit exceeded for tool ${name}. Please try again later.`,
343	              data: getRateLimitStatus(apiKey || clientIp, name),
344	            },
345	          });
346	        }
347	
348	        // ── ASYNC EXECUTION (if applicable) ──
349	        // FIX: shouldUseAsync 2nd arg is boolean (preferAsync from header), NOT the args object
350	        const preferAsync = req.headers['x-prefer-async'] === 'true';
351	        if (shouldUseAsync(name, preferAsync)) {
352	          // FIX: createAsyncJob takes (toolName, args, context: CreateJobOptions), not 4 separate args
353	          const { job: asyncJob, headers: jobHeaders } = createAsyncJob(name, normalizedArgs, {
354	            apiKey: apiKey || 'anonymous',
355	            clientIp,
356	            userAgent,
357	            callbackUrl: webhook?.url || webhook?.callback_url,
358	            callbackSecret: webhook?.secret,
359	            callbackHeaders: webhook?.headers,
360	          });
361	          const origin = `${req.protocol}://${req.get('host')}`;
362	          // FIX: pass the actual job object (not the wrapper) to buildJobResponse
363	          const response = buildJobResponse(asyncJob, origin);
364	          // Set job headers
365	          for (const [key, value] of Object.entries(jobHeaders)) {
366	            res.setHeader(key, value);
367	          }
368	          res.setHeader('Retry-After', response.retry_after_s?.toString() || '5');
369	
370	          // Start async execution in background.
371	          // Mirror the SYNC path's flag-gated, fail-open tenant resolution (this
372	          // tool is not normally routed async, but keep the ctx consistent).
373	          let asyncAuthenticatedTenant: { tenantId: string; source: string } | undefined;
374	          if (isFeatureEnabled('CANONICAL_VERDICT_RECEIPT_ENABLED')) {
375	            try { asyncAuthenticatedTenant = await resolveGovernedAuthenticatedTenant(req); } catch { asyncAuthenticatedTenant = undefined; }
376	          }
377	          executeTool(name, normalizedArgs, { apiKey, clientIp, userAgent, correlationId, requestId, authenticatedTenant: asyncAuthenticatedTenant })
378	            .then(result => {
379	              asyncJob.status = 'completed';
380	              asyncJob.result = result;
381	              asyncJob.completedAt = Date.now();
382	            })
383	            .catch(err => {
384	              asyncJob.status = 'failed';
385	              asyncJob.error = err instanceof Error ? err.message : String(err);
386	              asyncJob.completedAt = Date.now();
387	            });
388	
389	          return res.status(202).json(response);
390	        }
391	
392	        // ── GATE ENFORCEMENT (Nervous System Fix 4) ──
393	        // FIX: classifyGovernanceRequirement takes (args) not (name, args)
394	        // FIX: enforceGate takes (toolName, args, options) not (surface, options)
395	        // FIX: GateEnforcementResult uses 'allowed' not 'approved'
396	        try {
397	          // Extract approval_token from args so gate can validate it
398	          const approvalToken = (normalizedArgs as Record<string, unknown>).approval_token as string | undefined;
399	          const gateResult: GateEnforcementResult = enforceGate(name, normalizedArgs, {
400	            approvalToken,
401	          });
402	          if (!gateResult.allowed) {
403	            const envelope = buildGovernanceEnvelope(gateResult);
404	            return res.status(403).json({ jsonrpc: '2.0', id, result: { content: [{ type: 'text', text: JSON.stringify(envelope) }] } });
405	          }
406	        } catch (gateError) {
407	          generalLog.warn(`[MCP v2] Gate enforcement error (non-fatal, proceeding):`, gateError);
408	          // Non-fatal: proceed with tool execution even if gate check fails
409	        }
410	
411	        // ── TRUSTED TENANT RESOLUTION (flag-gated, fail-open) ──
412	        // Only when CANONICAL_VERDICT_RECEIPT_ENABLED — default-OFF ⇒ no
413	        // resolution runs ⇒ authenticatedTenant undefined ⇒ byte-identical ctx.
414	        // Spoof-proof: resolveInferenceTenant ignores x-gravito-tenant for a
415	        // provisioned tenant key. Fail-open: any error → undefined.
416	        let authenticatedTenant: { tenantId: string; source: string } | undefined;
417	        if (isFeatureEnabled('CANONICAL_VERDICT_RECEIPT_ENABLED')) {
418	          try { authenticatedTenant = await resolveGovernedAuthenticatedTenant(req); } catch { authenticatedTenant = undefined; }
419	        }
420	
421	        // ── SYNCHRONOUS EXECUTION with TIMEOUT ──
422	        const toolTimeoutMs = getToolTimeout(name);
423	        const executionPromise = executeTool(name, normalizedArgs, { apiKey, clientIp, userAgent, correlationId, requestId, authenticatedTenant });
424	
425	        const outcome = await withTimeout(executionPromise, toolTimeoutMs, name);
426	
427	        if (outcome.timedOut) {
428	          recordToolExecution(name, outcome.durationMs, true, false);
429	          generalLog.warn(`[MCP v2] Tool ${name} timed out after ${outcome.durationMs}ms (limit: ${toolTimeoutMs}ms)`);
430	
431	          logUsage({
432	            apiKey, ipAddress: clientIp, toolName: name, method: 'tools/call',
433	            success: false, errorMessage: `Tool execution timed out after ${outcome.durationMs}ms`,
434	            responseTimeMs: outcome.durationMs, userAgent,
435	          });
436	
437	          emitGovernanceEvent({
438	            type: 'error', source: 'mcp', tool: name,
439	            blocked: false,
440	            details: `Timeout after ${outcome.durationMs}ms (limit: ${toolTimeoutMs}ms)`,
441	            apiKeyPrefix: apiKey?.substring(0, 12),
442	            durationMs: outcome.durationMs,
443	          });
444	
445	          // ── AUDIT TRAIL (timeout) ──
446	          recordAudit(
447	            requestId, name, apiKey || 'anonymous', clientIp, userAgent,
448	            normalizedArgs, null, false, false, null, outcome.durationMs,
449	            `Timeout after ${outcome.durationMs}ms`,
450	          );
451	
452	          return res.json({
453	            jsonrpc: '2.0', id,
454	            result: {
455	              content: [{
456	                type: 'text',
457	                text: JSON.stringify(enrichMCPResponse({
458	                  success: false,
459	                  error: 'TOOL_TIMEOUT',
460	                  error_code: 'TIMEOUT',
461	                  message: `Tool ${name} exceeded the ${toolTimeoutMs}ms execution limit. The operation may still be running in the background. Try again with simpler input, or use a faster tool variant.`,
462	                  tool: name,
463	                  timeout_ms: toolTimeoutMs,
464	                  elapsed_ms: outcome.durationMs,
465	                  retry_suggestion: SLOW_TOOLS.has(name)
466	                    ? 'This is a complex tool. Consider breaking the request into smaller pieces or using mode=quick if available.'
467	                    : 'This tool should normally complete within the timeout. The server may be under heavy load — retry in a few seconds.',
468	                }, { correlationId, toolName: name, args: normalizedArgs, isError: true })),
469	              }],
470	            },
471	          });
472	        }
473	
474	        // Tool completed within timeout
475	        const result = outcome.result;
476	        const responseText = JSON.stringify(result);
477	        const durationMs = Date.now() - requestStart;
478	
479	        // Record success in health probe telemetry
480	        recordToolExecution(name, durationMs, false, isBlockedResponse(responseText));
481	
482	        logUsage({
483	          apiKey, ipAddress: clientIp, toolName: name, method: 'tools/call',
484	          success: true, responseTimeMs: durationMs,
485	          estimatedInputTokens: estimateTokens(JSON.stringify(params || {})),
486	          estimatedOutputTokens: estimateTokens(responseText),
487	          userAgent,
488	        });
489	
490	        emitGovernanceEvent({
491	          type: isBlockedResponse(responseText) ? 'block' : 'approval',
492	          source: 'mcp', tool: name,
493	          score: extractScore(responseText),
494	          blocked: isBlockedResponse(responseText),
495	          details: `${name} via MCP (${durationMs}ms)`,
496	          apiKeyPrefix: apiKey?.substring(0, 12),
497	          durationMs,
498	        });
499	
500	        generalLog.info(`[MCP] ${requestId} tools/call ${name} completed in ${durationMs}ms blocked=${isBlockedResponse(responseText)}`);
501	
502	        // ── AUDIT TRAIL ──
503	        recordAudit(
504	          requestId, name, apiKey || 'anonymous', clientIp, userAgent,
505	          normalizedArgs, result, true, isBlockedResponse(responseText),
506	          // @ts-ignore — argument type mismatch (interface drift)
507	          extractScore(responseText), durationMs,
508	        );
509	
510	        // Enrich successful response with governance metadata
511	        const enrichedResult = typeof result === 'object' && result !== null && 'content' in (result as EnrichedResult)
512	          ? {
513	              ...(result as EnrichedResult),
514	              content: (result as EnrichedResult).content?.map((c: { type: string; text: string }) => {
515	                if (c.type === 'text' && typeof c.text === 'string') {
516	                  try {
517	                    const parsed = JSON.parse(c.text);
518	                    const enriched = enrichMCPResponse(parsed, {
519	                      correlationId,
520	                      toolName: name,
521	                      args: normalizedArgs,
522	                      isError: false,
523	                    });
524	                    return { ...c, text: JSON.stringify(enriched) };
525	                  } catch { return c; }
526	                }
527	                return c;
528	              }),
529	            }
530	          : result;
531	
532	        return res.json({ jsonrpc: '2.0', id, result: enrichedResult });
533	      }
534	
535	      default:
536	        generalLog.warn(`[MCP] ${requestId} unknown method: ${method}`);
537	        return res.json({ jsonrpc: '2.0', id, error: { code: -32601, message: `Method not found: ${method}` } });
538	    }
539	  } catch (error: unknown) {
540	    generalLog.error('[MCP v2] Error:', error);
541	    if (error instanceof Error && error.stack) {
542	      generalLog.error('[MCP v2] FULL STACK TRACE:', error.stack);
543	    }
544	
545	    const apiKey = (req as Request & { apiKey?: string }).apiKey;
546	    const toolName = req.body?.method === 'tools/call' ? (req.body?.params?.name || 'unknown') : (req.body?.method || 'unknown');
547	    // Record error in health probe telemetry
548	    recordToolExecution(toolName, Date.now() - requestStart, false, true);
549	    logUsage({
