568	    }
569	    res.status(statusCode).json({
570	      jsonrpc: '2.0', id: req.body?.id,
571	      error: {
572	        code: -32603,
573	        message: error instanceof Error ? error.message : 'Internal error',
574	        data: {
575	          cause: classified.cause,
576	          description: classified.description,
577	          recoverable: classified.recoverable,
578	          retry_after_ms: classified.retry_after_ms,
579	          correlation_id: correlationId,
580	        },
581	      },
582	    });
583	  }
584	});
