1	/**
2	 * Async Job Queue for MCP Tools — First-Class Contract
3	 * 
4	 * Solves the CDN 15s proxy timeout by implementing the Async Job Pattern:
5	 * 1. Client calls tools/call → returns 202 Accepted with job_id + Retry-After
6	 * 2. Tool executes asynchronously in background
7	 * 3. Client polls /api/mcp/jobs/:id for status + result
8	 * 4. Optional: webhook callback delivers result when complete
9	 * 
10	 * Contract guarantees:
11	 * - 202 Accepted within 200ms for all async tools
12	 * - Retry-After header with adaptive backoff
13	 * - Webhook callback on completion/failure (if callback_url provided)
14	 * - Progress tracking for long-running tools
15	 * - Ownership-scoped access (API key isolation)
16	 * 
17	 * Built with Claude + Gravito governance architecture.
18	 */
19	
20	import { generalLog } from '../_core/logger';
21	import crypto from 'crypto';
22	
23	// ============================================================================
24	// TYPES
25	// ============================================================================
26	
27	export type AsyncJobStatus = 'queued' | 'running' | 'completed' | 'failed' | 'expired';
28	
29	export interface AsyncJobProgress {
30	  percent: number;       // 0-100
31	  stage: string;         // Human-readable stage name
32	  updatedAt: number;     // Unix ms
33	}
34	
35	export interface WebhookConfig {
36	  url: string;
37	  secret?: string;       // HMAC-SHA256 signing secret
38	  headers?: Record<string, string>;  // Custom headers
39	  maxRetries: number;
40	  retryDelayMs: number;
41	}
42	
43	export interface AsyncJob {
44	  id: string;
45	  toolName: string;
46	  args: Record<string, unknown>;
47	  status: AsyncJobStatus;
48	  result?: unknown;
49	  error?: string;
50	  createdAt: number;     // Unix ms
51	  startedAt?: number;
52	  completedAt?: number;
53	  ttlMs: number;         // Time-to-live for result storage
54	  apiKey: string;
55	  clientIp: string;
56	  userAgent: string;
57	  progress?: AsyncJobProgress;
58	  webhook?: WebhookConfig;
59	  webhookDelivered?: boolean;
60	  webhookAttempts?: number;
61	}
62	
63	export interface AsyncJobResponse {
64	  job_id: string;
65	  status: AsyncJobStatus;
66	  poll_url: string;
67	  poll_interval_ms: number;
68	  estimated_duration_ms: number;
69	  retry_after_s: number;           // Retry-After header value
70	  result?: unknown;
71	  error?: string;
72	  elapsed_ms?: number;
73	  progress?: AsyncJobProgress;
74	  webhook_configured?: boolean;
75	}
