77	export interface CreateJobOptions {
78	  apiKey: string;
79	  clientIp: string;
80	  userAgent: string;
81	  callbackUrl?: string;
82	  callbackSecret?: string;
83	  callbackHeaders?: Record<string, string>;
84	}
85	
86	// ============================================================================
87	// CONFIGURATION
88	// ============================================================================
89	
90	const CONFIG = {
91	  /** Max jobs stored in memory */
92	  maxJobs: 1000,
93	  /** Default TTL for completed job results (5 minutes) */
94	  defaultTtlMs: 5 * 60 * 1000,
95	  /** Cleanup interval (every 60 seconds) */
96	  cleanupIntervalMs: 60 * 1000,
97	  /** Tools that should use async execution (LLM-dependent, >5s typical) */
98	  // DISABLED: All tools now execute synchronously for MCP CLI compatibility.
99	  // The timeout system (15s default, 55s for SLOW_TOOLS) handles long-running tools.
100	  // Async mode can be re-enabled per-request via x-prefer-async: true header.
101	  asyncToolPatterns: [] as string[],
102	  /** Estimated duration by tool pattern (for client polling hints) */
103	  estimatedDurations: new Map<string, number>([
104	    ['reviewContent', 15000],
105	    ['generateGovernedContent', 20000],
106	    ['analyzeEmotionalGeometry', 12000],
107	    ['surfaceIntelligence', 18000],
108	    ['creativePartner', 25000],
109	    ['governancePlayground', 10000],
110	  ]),
111	  /** Default estimated duration for unknown tools */
112	  defaultEstimatedDuration: 15000,
113	  /** Webhook delivery timeout (10 seconds) */
114	  webhookTimeoutMs: 10000,
115	  /** Max webhook retries */
116	  maxWebhookRetries: 3,
117	  /** Webhook retry delay (exponential backoff base) */
118	  webhookRetryBaseMs: 2000,
119	  /** Adaptive Retry-After calculation */
120	  retryAfter: {
121	    queued: 3,    // seconds — check back in 3s when queued
122	    running: 2,   // seconds — check back in 2s when running
123	    completed: 0, // seconds — result ready
124	    failed: 0,    // seconds — terminal state
125	    expired: 0,   // seconds — terminal state
126	  } as Record<AsyncJobStatus, number>,
127	} as const;
128	
129	// ============================================================================
130	// IN-MEMORY STORE
131	// ============================================================================
132	
133	const jobs: Map<string, AsyncJob> = new Map();
134	
135	// ============================================================================
136	// CORE API
137	// ============================================================================
138	
139	/**
140	 * Get the estimated duration for a tool in milliseconds
141	 */
142	export function getEstimatedDuration(toolName: string): number {
143	  const shortName = toolName.replace('gravito.', '');
144	  return CONFIG.estimatedDurations.get(shortName) || CONFIG.defaultEstimatedDuration;
145	}
146	
147	/**
148	 * Check if a tool should use async execution
149	 */
150	export function shouldUseAsync(toolName: string, preferAsync?: boolean): boolean {
151	  // Client can force async via x-prefer-async header
152	  if (preferAsync === true) return true;
153	  
154	  const shortName = toolName.replace('gravito.', '');
155	  return CONFIG.asyncToolPatterns.some(pattern => 
156	    shortName.includes(pattern) || shortName === pattern
157	  );
158	}
159	
160	/**
161	 * Create an async job for a tool call
162	 * Returns the job and the 202 response headers
163	 */
164	export function createAsyncJob(
165	  toolName: string,
166	  args: Record<string, unknown>,
167	  context: CreateJobOptions
168	): { job: AsyncJob; headers: Record<string, string> } {
169	  // Enforce max jobs limit
170	  if (jobs.size >= CONFIG.maxJobs) {
171	    evictOldestCompleted();
172	  }
173	
174	  const id = `job_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`;
175	  const shortName = toolName.replace('gravito.', '');
176	  const estimatedMs = CONFIG.estimatedDurations.get(shortName) || CONFIG.defaultEstimatedDuration;
177	  const retryAfterS = CONFIG.retryAfter.queued;
178	
179	  const job: AsyncJob = {
180	    id,
181	    toolName,
182	    args,
183	    status: 'queued',
184	    createdAt: Date.now(),
185	    ttlMs: CONFIG.defaultTtlMs,
186	    apiKey: context.apiKey,
187	    clientIp: context.clientIp,
188	    userAgent: context.userAgent,
189	    progress: {
190	      percent: 0,
191	      stage: 'queued',
192	      updatedAt: Date.now(),
193	    },
194	  };
195	
196	  // Configure webhook if callback URL provided
197	  if (context.callbackUrl) {
198	    job.webhook = {
199	      url: context.callbackUrl,
200	      secret: context.callbackSecret,
201	      headers: context.callbackHeaders,
202	      maxRetries: CONFIG.maxWebhookRetries,
203	      retryDelayMs: CONFIG.webhookRetryBaseMs,
204	    };
205	    job.webhookDelivered = false;
206	    job.webhookAttempts = 0;
207	  }
208	
209	  jobs.set(id, job);
210	  generalLog.info(`[AsyncJobQueue] Created job ${id} for tool ${toolName} (webhook: ${!!context.callbackUrl})`);
211	
212	  // Build 202 response headers
213	  const headers: Record<string, string> = {
214	    'Retry-After': String(retryAfterS),
215	    'X-Job-Id': id,
216	    'X-Estimated-Duration-Ms': String(estimatedMs),
217	    'X-Poll-Url': `/api/mcp/jobs/${id}`,
218	  };
219	
220	  return { job, headers };
221	}
222	
223	/**
224	 * Mark a job as running with progress update
225	 */
226	export function markRunning(jobId: string): void {
227	  const job = jobs.get(jobId);
228	  if (job) {
229	    job.status = 'running';
230	    job.startedAt = Date.now();
231	    if (job.progress) {
232	      job.progress.percent = 10;
233	      job.progress.stage = 'executing';
234	      job.progress.updatedAt = Date.now();
235	    }
236	  }
237	}
238	
239	/**
240	 * Update job progress (for long-running tools)
241	 */
242	export function updateProgress(jobId: string, percent: number, stage: string): void {
243	  const job = jobs.get(jobId);
244	  if (job && job.status === 'running') {
245	    job.progress = {
246	      percent: Math.min(99, Math.max(0, percent)),
247	      stage,
248	      updatedAt: Date.now(),
249	    };
250	  }
251	}
252	
253	/**
254	 * Complete a job with result and trigger webhook if configured
255	 */
256	export function completeAsyncJob(jobId: string, result: unknown): void {
257	  const job = jobs.get(jobId);
258	  if (job) {
259	    job.status = 'completed';
260	    job.result = result;
261	    job.completedAt = Date.now();
262	    if (job.progress) {
263	      job.progress.percent = 100;
264	      job.progress.stage = 'completed';
265	      job.progress.updatedAt = Date.now();
266	    }
267	    const elapsed = job.completedAt - job.createdAt;
268	    generalLog.info(`[AsyncJobQueue] Job ${jobId} completed in ${elapsed}ms`);
269	
270	    // Trigger webhook delivery
271	    if (job.webhook && !job.webhookDelivered) {
272	      deliverWebhook(job, 'completed').catch(err => {
273	        generalLog.warn(`[AsyncJobQueue] Webhook delivery failed for job ${jobId}: ${err}`);
274	      });
275	    }
276	  }
277	}
278	
279	/**
280	 * Fail a job with error and trigger webhook if configured
281	 */
282	export function failAsyncJob(jobId: string, error: string): void {
283	  const job = jobs.get(jobId);
284	  if (job) {
285	    job.status = 'failed';
286	    job.error = error;
287	    job.completedAt = Date.now();
288	    if (job.progress) {
289	      job.progress.percent = 0;
290	      job.progress.stage = 'failed';
291	      job.progress.updatedAt = Date.now();
292	    }
293	    const elapsed = job.completedAt - job.createdAt;
294	    generalLog.warn(`[AsyncJobQueue] Job ${jobId} failed after ${elapsed}ms: ${error}`);
295	
296	    // Trigger webhook delivery
297	    if (job.webhook && !job.webhookDelivered) {
298	      deliverWebhook(job, 'failed').catch(err => {
299	        generalLog.warn(`[AsyncJobQueue] Webhook delivery failed for job ${jobId}: ${err}`);
300	      });
301	    }
302	  }
303	}
304	
305	/**
306	 * Get a job by ID (with ownership check)
307	 */
308	export function getJob(jobId: string, apiKey?: string): AsyncJob | null {
309	  const job = jobs.get(jobId);
310	  if (!job) return null;
311	  
312	  // Ownership check: only the creating API key can read the result
313	  if (apiKey && job.apiKey !== apiKey && job.apiKey !== 'dev-mode') {
314	    generalLog.warn(`[AsyncJobQueue] Unauthorized access to job ${jobId} from key ${apiKey?.substring(0, 12)}`);
315	    return null;
316	  }
317	  
318	  return job;
319	}
320	
321	/**
322	 * Build the client-facing response for a job with adaptive Retry-After
323	 */
324	export function buildJobResponse(job: AsyncJob, baseUrl: string): AsyncJobResponse {
325	  const shortName = job.toolName.replace('gravito.', '');
326	  const estimatedMs = CONFIG.estimatedDurations.get(shortName) || CONFIG.defaultEstimatedDuration;
327	  
328	  // Adaptive Retry-After based on status and elapsed time
329	  let retryAfterS = CONFIG.retryAfter[job.status] || 0;
330	  if (job.status === 'running' && job.startedAt) {
331	    const elapsed = Date.now() - job.startedAt;
332	    const remaining = Math.max(0, estimatedMs - elapsed);
333	    // If close to estimated completion, poll faster
334	    if (remaining < 3000) {
335	      retryAfterS = 1;
336	    } else if (remaining < 8000) {
337	      retryAfterS = 2;
338	    } else {
339	      retryAfterS = 3;
340	    }
341	  }
342	
343	  const response: AsyncJobResponse = {
344	    job_id: job.id,
345	    status: job.status,
346	    poll_url: `${baseUrl}/api/mcp/jobs/${job.id}`,
347	    poll_interval_ms: retryAfterS * 1000,
348	    estimated_duration_ms: estimatedMs,
349	    retry_after_s: retryAfterS,
350	    webhook_configured: !!job.webhook,
351	  };
352	
353	  if (job.progress) {
354	    response.progress = job.progress;
355	  }
356	
357	  if (job.status === 'completed') {
358	    response.result = job.result;
359	    response.elapsed_ms = (job.completedAt || Date.now()) - job.createdAt;
360	  }
361	
362	  if (job.status === 'failed') {
363	    response.error = job.error;
364	    response.elapsed_ms = (job.completedAt || Date.now()) - job.createdAt;
365	  }
366	
367	  if (job.status === 'running' || job.status === 'queued') {
368	    response.elapsed_ms = Date.now() - job.createdAt;
369	  }
370	
371	  return response;
372	}
373	
374	/**
375	 * Get queue statistics
376	 */
377	export function getAsyncQueueStats(): {
378	  total: number;
379	  queued: number;
380	  running: number;
381	  completed: number;
382	  failed: number;
383	  expired: number;
384	  avgCompletionMs: number;
385	  webhooksPending: number;
386	  webhooksDelivered: number;
387	  webhooksFailed: number;
388	} {
389	  let queued = 0, running = 0, completed = 0, failed = 0, expired = 0;
390	  let totalCompletionMs = 0;
391	  let completedCount = 0;
392	  let webhooksPending = 0, webhooksDelivered = 0, webhooksFailed = 0;
393	
394	  for (const job of jobs.values()) {
395	    switch (job.status) {
396	      case 'queued': queued++; break;
397	      case 'running': running++; break;
398	      case 'completed': 
399	        completed++;
400	        if (job.completedAt) {
401	          totalCompletionMs += job.completedAt - job.createdAt;
402	          completedCount++;
403	        }
404	        break;
405	      case 'failed': failed++; break;
406	      case 'expired': expired++; break;
407	    }
408	
409	    // Webhook stats
410	    if (job.webhook) {
411	      if (job.webhookDelivered) {
412	        webhooksDelivered++;
413	      } else if (job.status === 'completed' || job.status === 'failed') {
414	        webhooksFailed++;
415	      } else {
416	        webhooksPending++;
417	      }
418	    }
419	  }
420	
421	  return {
422	    total: jobs.size,
423	    queued,
424	    running,
425	    completed,
426	    failed,
427	    expired,
428	    avgCompletionMs: completedCount > 0 ? Math.round(totalCompletionMs / completedCount) : 0,
429	    webhooksPending,
430	    webhooksDelivered,
431	    webhooksFailed,
432	  };
433	}
434	
435	// ============================================================================
436	// WEBHOOK DELIVERY
437	// ============================================================================
438	
439	/**
440	 * Deliver webhook callback with HMAC-SHA256 signing and exponential backoff retry
441	 */
442	async function deliverWebhook(job: AsyncJob, event: 'completed' | 'failed'): Promise<void> {
443	  if (!job.webhook) return;
444	
445	  const payload = JSON.stringify({
446	    event: `job.${event}`,
447	    job_id: job.id,
448	    tool_name: job.toolName,
449	    status: job.status,
450	    result: job.result,
451	    error: job.error,
452	    elapsed_ms: job.completedAt ? job.completedAt - job.createdAt : undefined,
453	    timestamp: new Date().toISOString(),
454	  });
455	
456	  const headers: Record<string, string> = {
457	    'Content-Type': 'application/json',
458	    'User-Agent': 'EmpathIQ-Webhook/1.0',
459	    'X-Job-Id': job.id,
460	    'X-Event': `job.${event}`,
461	    ...(job.webhook.headers || {}),
462	  };
463	
464	  // HMAC-SHA256 signature if secret provided
465	  if (job.webhook.secret) {
466	    const signature = crypto
467	      .createHmac('sha256', job.webhook.secret)
468	      .update(payload)
469	      .digest('hex');
470	    headers['X-Signature-256'] = `sha256=${signature}`;
471	  }
472	
473	  for (let attempt = 0; attempt <= job.webhook.maxRetries; attempt++) {
474	    job.webhookAttempts = (job.webhookAttempts || 0) + 1;
475	
476	    try {
477	      const controller = new AbortController();
478	      const timeout = setTimeout(() => controller.abort(), CONFIG.webhookTimeoutMs);
479	
480	      const response = await fetch(job.webhook.url, {
481	        method: 'POST',
482	        headers,
483	        body: payload,
484	        signal: controller.signal,
485	      });
486	
487	      clearTimeout(timeout);
488	
489	      if (response.ok || response.status < 500) {
490	        job.webhookDelivered = true;
491	        generalLog.info(`[AsyncJobQueue] Webhook delivered for job ${job.id} (attempt ${attempt + 1}, status ${response.status})`);
492	        return;
493	      }
494	
495	      generalLog.warn(`[AsyncJobQueue] Webhook attempt ${attempt + 1} for job ${job.id} returned ${response.status}`);
496	    } catch (err: unknown) {
497	      const errMsg = err instanceof Error ? err.message : String(err);
498	      generalLog.warn(`[AsyncJobQueue] Webhook attempt ${attempt + 1} for job ${job.id} failed: ${errMsg}`);
499	    }
500	
501	    // Exponential backoff before retry
502	    if (attempt < job.webhook.maxRetries) {
503	      const delay = job.webhook.retryDelayMs * Math.pow(2, attempt);
504	      await new Promise(resolve => setTimeout(resolve, delay));
505	    }
506	  }
507	
508	  generalLog.error(`[AsyncJobQueue] Webhook delivery exhausted for job ${job.id} after ${job.webhookAttempts} attempts`);
509	}
510	
511	// ============================================================================
512	// CLEANUP
513	// ============================================================================
514	
515	function evictOldestCompleted(): void {
516	  let oldest: { id: string; time: number } | null = null;
517	  for (const [id, job] of jobs) {
518	    if (job.status === 'completed' || job.status === 'failed' || job.status === 'expired') {
519	      const time = job.completedAt || job.createdAt;
520	      if (!oldest || time < oldest.time) {
521	        oldest = { id, time };
522	      }
523	    }
524	  }
525	  if (oldest) {
526	    jobs.delete(oldest.id);
527	    generalLog.info(`[AsyncJobQueue] Evicted oldest completed job ${oldest.id}`);
528	  }
529	}
530	
531	// ============================================================================
532	// JOB MANAGEMENT — LIST & CANCEL (Nervous System Fix 5)
533	// ============================================================================
534	
535	/**
536	 * List jobs for a given API key with optional status filter.
537	 * Returns jobs sorted by creation time (newest first).
538	 */
539	export function listJobs(
540	  apiKey: string,
541	  options?: { status?: AsyncJobStatus; limit?: number; offset?: number }
542	): { jobs: AsyncJob[]; total: number; filtered: number } {
543	  const limit = Math.min(options?.limit || 20, 100);
544	  const offset = options?.offset || 0;
545	  
546	  let matching: AsyncJob[] = [];
547	  for (const job of jobs.values()) {
548	    if (job.apiKey !== apiKey) continue;
549	    if (options?.status && job.status !== options.status) continue;
550	    matching.push(job);
551	  }
552	  
553	  // Sort by creation time, newest first
554	  matching.sort((a, b) => b.createdAt - a.createdAt);
555	  
556	  const total = matching.length;
557	  const paginated = matching.slice(offset, offset + limit);
558	  
559	  return { jobs: paginated, total, filtered: paginated.length };
560	}
561	
562	/**
563	 * Cancel a pending or running job.
564	 * Returns true if the job was cancelled, false if not found or already terminal.
565	 */
