/**
 * Async Job Queue for MCP Tools — First-Class Contract
 * 
 * Solves the CDN 15s proxy timeout by implementing the Async Job Pattern:
 * 1. Client calls tools/call → returns 202 Accepted with job_id + Retry-After
 * 2. Tool executes asynchronously in background
 * 3. Client polls /api/mcp/jobs/:id for status + result
 * 4. Optional: webhook callback delivers result when complete
 * 
 * Contract guarantees:
 * - 202 Accepted within 200ms for all async tools
 * - Retry-After header with adaptive backoff
 * - Webhook callback on completion/failure (if callback_url provided)
 * - Progress tracking for long-running tools
 * - Ownership-scoped access (API key isolation)
 * 
 * Built with Claude + Gravito governance architecture.
 */

import { generalLog } from '../_core/logger';
import crypto from 'crypto';

// ============================================================================
// TYPES
// ============================================================================

export type AsyncJobStatus = 'queued' | 'running' | 'completed' | 'failed' | 'expired';

export interface AsyncJobProgress {
  percent: number;       // 0-100
  stage: string;         // Human-readable stage name
  updatedAt: number;     // Unix ms
}

export interface WebhookConfig {
  url: string;
  secret?: string;       // HMAC-SHA256 signing secret
  headers?: Record<string, string>;  // Custom headers
  maxRetries: number;
  retryDelayMs: number;
}

export interface AsyncJob {
  id: string;
  toolName: string;
  args: Record<string, unknown>;
  status: AsyncJobStatus;
  result?: unknown;
  error?: string;
  createdAt: number;     // Unix ms
  startedAt?: number;
  completedAt?: number;
  ttlMs: number;         // Time-to-live for result storage
  apiKey: string;
  clientIp: string;
  userAgent: string;
  progress?: AsyncJobProgress;
  webhook?: WebhookConfig;
  webhookDelivered?: boolean;
  webhookAttempts?: number;
}

export interface AsyncJobResponse {
  job_id: string;
  status: AsyncJobStatus;
  poll_url: string;
  poll_interval_ms: number;
  estimated_duration_ms: number;
  retry_after_s: number;           // Retry-After header value
  result?: unknown;
  error?: string;
  elapsed_ms?: number;
  progress?: AsyncJobProgress;
  webhook_configured?: boolean;
}

export interface CreateJobOptions {
  apiKey: string;
  clientIp: string;
  userAgent: string;
  callbackUrl?: string;
  callbackSecret?: string;
  callbackHeaders?: Record<string, string>;
}

// ============================================================================
// CONFIGURATION
// ============================================================================

const CONFIG = {
  /** Max jobs stored in memory */
  maxJobs: 1000,
  /** Default TTL for completed job results (5 minutes) */
  defaultTtlMs: 5 * 60 * 1000,
  /** Cleanup interval (every 60 seconds) */
  cleanupIntervalMs: 60 * 1000,
  /** Tools that should use async execution (LLM-dependent, >5s typical) */
  // DISABLED: All tools now execute synchronously for MCP CLI compatibility.
  // The timeout system (15s default, 55s for SLOW_TOOLS) handles long-running tools.
  // Async mode can be re-enabled per-request via x-prefer-async: true header.
  asyncToolPatterns: [] as string[],
  /** Estimated duration by tool pattern (for client polling hints) */
  estimatedDurations: new Map<string, number>([
    ['reviewContent', 15000],
    ['generateGovernedContent', 20000],
    ['analyzeEmotionalGeometry', 12000],
    ['surfaceIntelligence', 18000],
    ['creativePartner', 25000],
    ['governancePlayground', 10000],
  ]),
  /** Default estimated duration for unknown tools */
  defaultEstimatedDuration: 15000,
  /** Webhook delivery timeout (10 seconds) */
  webhookTimeoutMs: 10000,
  /** Max webhook retries */
  maxWebhookRetries: 3,
  /** Webhook retry delay (exponential backoff base) */
  webhookRetryBaseMs: 2000,
  /** Adaptive Retry-After calculation */
  retryAfter: {
    queued: 3,    // seconds — check back in 3s when queued
    running: 2,   // seconds — check back in 2s when running
    completed: 0, // seconds — result ready
    failed: 0,    // seconds — terminal state
    expired: 0,   // seconds — terminal state
  } as Record<AsyncJobStatus, number>,
} as const;

// ============================================================================
// IN-MEMORY STORE
// ============================================================================

const jobs: Map<string, AsyncJob> = new Map();

// ============================================================================
// CORE API
// ============================================================================

/**
 * Get the estimated duration for a tool in milliseconds
 */
export function getEstimatedDuration(toolName: string): number {
  const shortName = toolName.replace('gravito.', '');
  return CONFIG.estimatedDurations.get(shortName) || CONFIG.defaultEstimatedDuration;
}

/**
 * Check if a tool should use async execution
 */
export function shouldUseAsync(toolName: string, preferAsync?: boolean): boolean {
  // Client can force async via x-prefer-async header
  if (preferAsync === true) return true;

  const shortName = toolName.replace('gravito.', '');
  return CONFIG.asyncToolPatterns.some(pattern => 
    shortName.includes(pattern) || shortName === pattern
  );
}

/**
 * Create an async job for a tool call
 * Returns the job and the 202 response headers
 */
export function createAsyncJob(
  toolName: string,
  args: Record<string, unknown>,
  context: CreateJobOptions
): { job: AsyncJob; headers: Record<string, string> } {
  // Enforce max jobs limit
  if (jobs.size >= CONFIG.maxJobs) {
    evictOldestCompleted();
  }

  const id = `job_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`;
  const shortName = toolName.replace('gravito.', '');
  const estimatedMs = CONFIG.estimatedDurations.get(shortName) || CONFIG.defaultEstimatedDuration;
  const retryAfterS = CONFIG.retryAfter.queued;

  const job: AsyncJob = {
    id,
    toolName,
    args,
    status: 'queued',
    createdAt: Date.now(),
    ttlMs: CONFIG.defaultTtlMs,
    apiKey: context.apiKey,
    clientIp: context.clientIp,
    userAgent: context.userAgent,
    progress: {
      percent: 0,
      stage: 'queued',
      updatedAt: Date.now(),
    },
  };

  // Configure webhook if callback URL provided
  if (context.callbackUrl) {
    job.webhook = {
      url: context.callbackUrl,
      secret: context.callbackSecret,
      headers: context.callbackHeaders,
      maxRetries: CONFIG.maxWebhookRetries,
      retryDelayMs: CONFIG.webhookRetryBaseMs,
    };
    job.webhookDelivered = false;
    job.webhookAttempts = 0;
  }

  jobs.set(id, job);
  generalLog.info(`[AsyncJobQueue] Created job ${id} for tool ${toolName} (webhook: ${!!context.callbackUrl})`);

  // Build 202 response headers
  const headers: Record<string, string> = {
    'Retry-After': String(retryAfterS),
    'X-Job-Id': id,
    'X-Estimated-Duration-Ms': String(estimatedMs),
    'X-Poll-Url': `/api/mcp/jobs/${id}`,
  };

  return { job, headers };
}

/**
 * Mark a job as running with progress update
 */
export function markRunning(jobId: string): void {
  const job = jobs.get(jobId);
  if (job) {
    job.status = 'running';
    job.startedAt = Date.now();
    if (job.progress) {
      job.progress.percent = 10;
      job.progress.stage = 'executing';
      job.progress.updatedAt = Date.now();
    }
  }
}

/**
 * Update job progress (for long-running tools)
 */
export function updateProgress(jobId: string, percent: number, stage: string): void {
  const job = jobs.get(jobId);
  if (job && job.status === 'running') {
    job.progress = {
      percent: Math.min(99, Math.max(0, percent)),
      stage,
      updatedAt: Date.now(),
    };
  }
}

/**
 * Complete a job with result and trigger webhook if configured
 */
export function completeAsyncJob(jobId: string, result: unknown): void {
  const job = jobs.get(jobId);
  if (job) {
    job.status = 'completed';
    job.result = result;
    job.completedAt = Date.now();
    if (job.progress) {
      job.progress.percent = 100;
      job.progress.stage = 'completed';
      job.progress.updatedAt = Date.now();
    }
    const elapsed = job.completedAt - job.createdAt;
    generalLog.info(`[AsyncJobQueue] Job ${jobId} completed in ${elapsed}ms`);

    // Trigger webhook delivery
    if (job.webhook && !job.webhookDelivered) {
      deliverWebhook(job, 'completed').catch(err => {
        generalLog.warn(`[AsyncJobQueue] Webhook delivery failed for job ${jobId}: ${err}`);
      });
    }
  }
}

/**
 * Fail a job with error and trigger webhook if configured
 */
export function failAsyncJob(jobId: string, error: string): void {
  const job = jobs.get(jobId);
  if (job) {
    job.status = 'failed';
    job.error = error;
    job.completedAt = Date.now();
    if (job.progress) {
      job.progress.percent = 0;
      job.progress.stage = 'failed';
      job.progress.updatedAt = Date.now();
    }
    const elapsed = job.completedAt - job.createdAt;
    generalLog.warn(`[AsyncJobQueue] Job ${jobId} failed after ${elapsed}ms: ${error}`);

    // Trigger webhook delivery
    if (job.webhook && !job.webhookDelivered) {
      deliverWebhook(job, 'failed').catch(err => {
        generalLog.warn(`[AsyncJobQueue] Webhook delivery failed for job ${jobId}: ${err}`);
      });
    }
  }
}

/**
 * Get a job by ID (with ownership check)
 */
export function getJob(jobId: string, apiKey?: string): AsyncJob | null {
  const job = jobs.get(jobId);
  if (!job) return null;

  // Ownership check: only the creating API key can read the result
  if (apiKey && job.apiKey !== apiKey && job.apiKey !== 'dev-mode') {
    generalLog.warn(`[AsyncJobQueue] Unauthorized access to job ${jobId} from key ${apiKey?.substring(0, 12)}`);
    return null;
  }

  return job;
}

/**
 * Build the client-facing response for a job with adaptive Retry-After
 */
export function buildJobResponse(job: AsyncJob, baseUrl: string): AsyncJobResponse {
  const shortName = job.toolName.replace('gravito.', '');
  const estimatedMs = CONFIG.estimatedDurations.get(shortName) || CONFIG.defaultEstimatedDuration;

  // Adaptive Retry-After based on status and elapsed time
  let retryAfterS = CONFIG.retryAfter[job.status] || 0;
  if (job.status === 'running' && job.startedAt) {
    const elapsed = Date.now() - job.startedAt;
    const remaining = Math.max(0, estimatedMs - elapsed);
    // If close to estimated completion, poll faster
    if (remaining < 3000) {
      retryAfterS = 1;
    } else if (remaining < 8000) {
      retryAfterS = 2;
    } else {
      retryAfterS = 3;
    }
  }

  const response: AsyncJobResponse = {
    job_id: job.id,
    status: job.status,
    poll_url: `${baseUrl}/api/mcp/jobs/${job.id}`,
    poll_interval_ms: retryAfterS * 1000,
    estimated_duration_ms: estimatedMs,
    retry_after_s: retryAfterS,
    webhook_configured: !!job.webhook,
  };

  if (job.progress) {
    response.progress = job.progress;
  }

  if (job.status === 'completed') {
    response.result = job.result;
    response.elapsed_ms = (job.completedAt || Date.now()) - job.createdAt;
  }

  if (job.status === 'failed') {
    response.error = job.error;
    response.elapsed_ms = (job.completedAt || Date.now()) - job.createdAt;
  }

  if (job.status === 'running' || job.status === 'queued') {
    response.elapsed_ms = Date.now() - job.createdAt;
  }

  return response;
}

/**
 * Get queue statistics
 */
export function getAsyncQueueStats(): {
  total: number;
  queued: number;
  running: number;
  completed: number;
  failed: number;
  expired: number;
  avgCompletionMs: number;
  webhooksPending: number;
  webhooksDelivered: number;
  webhooksFailed: number;
} {
  let queued = 0, running = 0, completed = 0, failed = 0, expired = 0;
  let totalCompletionMs = 0;
  let completedCount = 0;
  let webhooksPending = 0, webhooksDelivered = 0, webhooksFailed = 0;

  for (const job of jobs.values()) {
    switch (job.status) {
      case 'queued': queued++; break;
      case 'running': running++; break;
      case 'completed': 
        completed++;
        if (job.completedAt) {
          totalCompletionMs += job.completedAt - job.createdAt;
          completedCount++;
        }
        break;
      case 'failed': failed++; break;
      case 'expired': expired++; break;
    }

    // Webhook stats
    if (job.webhook) {
      if (job.webhookDelivered) {
        webhooksDelivered++;
      } else if (job.status === 'completed' || job.status === 'failed') {
        webhooksFailed++;
      } else {
        webhooksPending++;
      }
    }
  }

  return {
    total: jobs.size,
    queued,
    running,
    completed,
    failed,
    expired,
    avgCompletionMs: completedCount > 0 ? Math.round(totalCompletionMs / completedCount) : 0,
    webhooksPending,
    webhooksDelivered,
    webhooksFailed,
  };
}

// ============================================================================
// WEBHOOK DELIVERY
// ============================================================================

/**
 * Deliver webhook callback with HMAC-SHA256 signing and exponential backoff retry
 */
async function deliverWebhook(job: AsyncJob, event: 'completed' | 'failed'): Promise<void> {
  if (!job.webhook) return;

  const payload = JSON.stringify({
    event: `job.${event}`,
    job_id: job.id,
    tool_name: job.toolName,
    status: job.status,
    result: job.result,
    error: job.error,
    elapsed_ms: job.completedAt ? job.completedAt - job.createdAt : undefined,
    timestamp: new Date().toISOString(),
  });

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'User-Agent': 'EmpathIQ-Webhook/1.0',
    'X-Job-Id': job.id,
    'X-Event': `job.${event}`,
    ...(job.webhook.headers || {}),
  };

  // HMAC-SHA256 signature if secret provided
  if (job.webhook.secret) {
    const signature = crypto
      .createHmac('sha256', job.webhook.secret)
      .update(payload)
      .digest('hex');
    headers['X-Signature-256'] = `sha256=${signature}`;
  }

  for (let attempt = 0; attempt <= job.webhook.maxRetries; attempt++) {
    job.webhookAttempts = (job.webhookAttempts || 0) + 1;

    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), CONFIG.webhookTimeoutMs);

      const response = await fetch(job.webhook.url, {
        method: 'POST',
        headers,
        body: payload,
        signal: controller.signal,
      });

      clearTimeout(timeout);

      if (response.ok || response.status < 500) {
        job.webhookDelivered = true;
        generalLog.info(`[AsyncJobQueue] Webhook delivered for job ${job.id} (attempt ${attempt + 1}, status ${response.status})`);
        return;
      }

      generalLog.warn(`[AsyncJobQueue] Webhook attempt ${attempt + 1} for job ${job.id} returned ${response.status}`);
    } catch (err: unknown) {
      const errMsg = err instanceof Error ? err.message : String(err);
      generalLog.warn(`[AsyncJobQueue] Webhook attempt ${attempt + 1} for job ${job.id} failed: ${errMsg}`);
    }

    // Exponential backoff before retry
    if (attempt < job.webhook.maxRetries) {
      const delay = job.webhook.retryDelayMs * Math.pow(2, attempt);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }

  generalLog.error(`[AsyncJobQueue] Webhook delivery exhausted for job ${job.id} after ${job.webhookAttempts} attempts`);
}

// ============================================================================
// CLEANUP
// ============================================================================

function evictOldestCompleted(): void {
  let oldest: { id: string; time: number } | null = null;
  for (const [id, job] of jobs) {
    if (job.status === 'completed' || job.status === 'failed' || job.status === 'expired') {
      const time = job.completedAt || job.createdAt;
      if (!oldest || time < oldest.time) {
        oldest = { id, time };
      }
    }
  }
  if (oldest) {
    jobs.delete(oldest.id);
    generalLog.info(`[AsyncJobQueue] Evicted oldest completed job ${oldest.id}`);
  }
}

// ============================================================================
// JOB MANAGEMENT — LIST & CANCEL (Nervous System Fix 5)
// ============================================================================

/**
 * List jobs for a given API key with optional status filter.
 * Returns jobs sorted by creation time (newest first).
 */
export function listJobs(
  apiKey: string,
  options?: { status?: AsyncJobStatus; limit?: number; offset?: number }
): { jobs: AsyncJob[]; total: number; filtered: number } {
  const limit = Math.min(options?.limit || 20, 100);
  const offset = options?.offset || 0;

  let matching: AsyncJob[] = [];
  for (const job of jobs.values()) {
    if (job.apiKey !== apiKey) continue;
    if (options?.status && job.status !== options.status) continue;
    matching.push(job);
  }

  // Sort by creation time, newest first
  matching.sort((a, b) => b.createdAt - a.createdAt);

  const total = matching.length;
  const paginated = matching.slice(offset, offset + limit);

  return { jobs: paginated, total, filtered: paginated.length };
}

/**
 * Cancel a pending or running job.
 * Returns true if the job was cancelled, false if not found or already terminal.
 */
export function cancelJob(jobId: string, apiKey: string): { cancelled: boolean; reason?: string } {
  const job = jobs.get(jobId);

  if (!job) {
    return { cancelled: false, reason: 'Job not found' };
  }

  if (job.apiKey !== apiKey) {
    return { cancelled: false, reason: 'Access denied' };
  }

  if (job.status === 'completed' || job.status === 'failed' || job.status === 'expired') {
    return { cancelled: false, reason: `Job already in terminal state: ${job.status}` };
  }

  job.status = 'failed';
  job.error = 'Cancelled by client';
  job.completedAt = Date.now();
  generalLog.info(`[AsyncJobQueue] Job ${jobId} cancelled by client (apiKey: ${apiKey.substring(0, 8)}...)`);

  return { cancelled: true };
}

export function cleanupExpiredJobs(): number {
  const now = Date.now();
  let cleaned = 0;

  for (const [id, job] of jobs) {
    if ((job.status === 'completed' || job.status === 'failed') && 
        job.completedAt && (now - job.completedAt) > job.ttlMs) {
      job.status = 'expired';
      jobs.delete(id);
      cleaned++;
    }
  }

  if (cleaned > 0) {
    generalLog.info(`[AsyncJobQueue] Cleaned up ${cleaned} expired jobs`);
  }
  return cleaned;
}

// Start cleanup interval
let cleanupTimer: ReturnType<typeof setInterval> | null = null;

export function startCleanup(): void {
  if (cleanupTimer) return;
  cleanupTimer = setInterval(() => {
    try {
      cleanupExpiredJobs();
    } catch (err) {
      generalLog.warn(
        `[AsyncJobQueue] cleanup failed: ${err instanceof Error ? err.message : String(err)}`
      );
    }
  }, CONFIG.cleanupIntervalMs);
  // Don't block process exit
  if (cleanupTimer.unref) cleanupTimer.unref();
}

export function stopCleanup(): void {
  if (cleanupTimer) {
    clearInterval(cleanupTimer);
    cleanupTimer = null;
  }
}

// Auto-start cleanup
startCleanup();

// ============================================================================
// EXPORTS FOR TESTING
// ============================================================================

export const _testOnly = {
  jobs,
  CONFIG,
  evictOldestCompleted,
  deliverWebhook,
};

