1	/**
2	 * MCP Audit Trail
3	 * 
4	 * Persistent structured logging of all MCP tool invocations for compliance.
5	 * Stores to database with full call metadata, response summaries, and governance decisions.
6	 * 
7	 * Designed for:
8	 * - Enterprise compliance audits (HIPAA, SOC2, GDPR)
9	 * - Debugging and incident investigation
10	 * - Usage analytics and billing
11	 * - Governance decision transparency
12	 */
13	
14	import { createLogger } from '../_core/logger';
15	import { getDb } from '../db';
16	import { sql } from 'drizzle-orm';
17	
18	const log = createLogger('mcp-audit');
19	
20	// ============================================================================
21	// AUDIT RECORD TYPE
22	// ============================================================================
23	
24	export interface AuditRecord {
25	  requestId: string;
26	  toolName: string;
27	  apiKeyPrefix: string;
28	  clientIp: string;
29	  userAgent: string;
30	  inputSummary: string;       // Truncated/sanitized input (no PII)
31	  outputSummary: string;      // Truncated output summary
32	  success: boolean;
33	  blocked: boolean;
34	  score: number | null;
35	  durationMs: number;
36	  errorMessage?: string;
37	  gravitoRunId?: string;
38	  decisionTraceId?: string;
39	  timestamp: number;
40	}
41	
42	// ============================================================================
43	// INPUT SANITIZATION
44	// ============================================================================
45	
46	function sanitizeInput(args: Record<string, unknown>): string {
47	  // Remove potentially sensitive fields, truncate content
48	  const sanitized: Record<string, unknown> = {};
49	  for (const [key, value] of Object.entries(args)) {
50	    if (['api_key', 'token', 'password', 'secret', 'authorization'].includes(key.toLowerCase())) {
51	      sanitized[key] = '[REDACTED]';
52	    } else if (typeof value === 'string' && value.length > 200) {
53	      sanitized[key] = value.slice(0, 200) + '...[truncated]';
54	    } else {
55	      sanitized[key] = value;
56	    }
57	  }
58	  return JSON.stringify(sanitized).slice(0, 1000);
59	}
60	
61	function summarizeOutput(result: unknown): string {
62	  const max = 500;
63	  try {
64	    const str = JSON.stringify(result, (_key, val) => {
65	      if (typeof val === "string" && val.length > 200) {
66	        return `${val.slice(0, 200)}…`;
67	      }
68	      return val;
69	    });
70	    return str.length <= max ? str : str.slice(0, max) + "...[truncated]";
71	  } catch {
72	    return "[unserializable]";
73	  }
74	}
75	
76	function extractGravitoRunId(result: unknown): string | undefined {
77	  if (result && typeof result === 'object') {
78	    const r = result as unknown as Record<string, unknown>;
79	    if (typeof r.gravito_run_id === 'string') return r.gravito_run_id;
80	    // Check nested in content array (MCP response format)
