/**
 * MCP Audit Trail
 * 
 * Persistent structured logging of all MCP tool invocations for compliance.
 * Stores to database with full call metadata, response summaries, and governance decisions.
 * 
 * Designed for:
 * - Enterprise compliance audits (HIPAA, SOC2, GDPR)
 * - Debugging and incident investigation
 * - Usage analytics and billing
 * - Governance decision transparency
 */

import { createLogger } from '../_core/logger';
import { getDb } from '../db';
import { sql } from 'drizzle-orm';

const log = createLogger('mcp-audit');

// ============================================================================
// AUDIT RECORD TYPE
// ============================================================================

export interface AuditRecord {
  requestId: string;
  toolName: string;
  apiKeyPrefix: string;
  clientIp: string;
  userAgent: string;
  inputSummary: string;       // Truncated/sanitized input (no PII)
  outputSummary: string;      // Truncated output summary
  success: boolean;
  blocked: boolean;
  score: number | null;
  durationMs: number;
  errorMessage?: string;
  gravitoRunId?: string;
  decisionTraceId?: string;
  timestamp: number;
}

// ============================================================================
// INPUT SANITIZATION
// ============================================================================

function sanitizeInput(args: Record<string, unknown>): string {
  // Remove potentially sensitive fields, truncate content
  const sanitized: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(args)) {
    if (['api_key', 'token', 'password', 'secret', 'authorization'].includes(key.toLowerCase())) {
      sanitized[key] = '[REDACTED]';
    } else if (typeof value === 'string' && value.length > 200) {
      sanitized[key] = value.slice(0, 200) + '...[truncated]';
    } else {
      sanitized[key] = value;
    }
  }
  return JSON.stringify(sanitized).slice(0, 1000);
}

function summarizeOutput(result: unknown): string {
  const max = 500;
  try {
    const str = JSON.stringify(result, (_key, val) => {
      if (typeof val === "string" && val.length > 200) {
        return `${val.slice(0, 200)}…`;
      }
      return val;
    });
    return str.length <= max ? str : str.slice(0, max) + "...[truncated]";
  } catch {
    return "[unserializable]";
  }
}

function extractGravitoRunId(result: unknown): string | undefined {
  if (result && typeof result === 'object') {
    const r = result as unknown as Record<string, unknown>;
    if (typeof r.gravito_run_id === 'string') return r.gravito_run_id;
    // Check nested in content array (MCP response format)
    if (Array.isArray(r.content)) {
      for (const item of r.content) {
        if (item && typeof item === 'object' && 'text' in item && typeof item.text === 'string') {
          try {
            const parsed = JSON.parse(item.text);
            if (typeof parsed.gravito_run_id === 'string') return parsed.gravito_run_id;
          } catch { /* not JSON */ }
        }
      }
    }
  }
  return undefined;
}

function extractDecisionTraceId(result: unknown): string | undefined {
  if (result && typeof result === 'object') {
    const r = result as unknown as Record<string, unknown>;
    if (typeof r.decision_trace_id === 'string') return r.decision_trace_id;
    if (Array.isArray(r.content)) {
      for (const item of r.content) {
        if (item && typeof item === 'object' && 'text' in item && typeof item.text === 'string') {
          try {
            const parsed = JSON.parse(item.text);
            if (typeof parsed.decision_trace_id === 'string') return parsed.decision_trace_id;
          } catch { /* not JSON */ }
        }
      }
    }
  }
  return undefined;
}

// ============================================================================
// IN-MEMORY BUFFER (batch writes to reduce DB pressure)
// ============================================================================

const BUFFER: AuditRecord[] = [];
const FLUSH_INTERVAL_MS = 10_000; // Flush every 10 seconds
const MAX_BUFFER_SIZE = 50;       // Or when buffer hits 50 records
let flushTimer: NodeJS.Timeout | null = null;

async function flushBuffer(): Promise<void> {
  if (BUFFER.length === 0) return;

  const batch = BUFFER.splice(0, BUFFER.length);

  try {
    // Insert batch into audit table
    const values = batch.map(r => 
      `(${esc(r.requestId)}, ${esc(r.toolName)}, ${esc(r.apiKeyPrefix)}, ${esc(r.clientIp)}, ${esc(r.userAgent.slice(0, 200))}, ${esc(r.inputSummary)}, ${esc(r.outputSummary)}, ${r.success ? 1 : 0}, ${r.blocked ? 1 : 0}, ${r.score ?? 'NULL'}, ${r.durationMs}, ${r.errorMessage ? esc(r.errorMessage.slice(0, 500)) : 'NULL'}, ${r.gravitoRunId ? esc(r.gravitoRunId) : 'NULL'}, ${r.decisionTraceId ? esc(r.decisionTraceId) : 'NULL'}, ${r.timestamp})`
    ).join(',\n');

    const db = await getDb();
    await db?.execute(sql.raw(`
      INSERT INTO mcp_audit_trail (request_id, tool_name, api_key_prefix, client_ip, user_agent, input_summary, output_summary, success, blocked, score, duration_ms, error_message, gravito_run_id, decision_trace_id, created_at)
      VALUES ${values}
    `));

    log.info(`[Audit] Flushed ${batch.length} records to database`);
  } catch (error) {
    // On DB failure, log to console as fallback (never lose audit records)
    log.error(`[Audit] Failed to flush ${batch.length} records to DB:`, error);
    for (const record of batch) {
      log.warn(`[Audit FALLBACK] ${JSON.stringify(record)}`);
    }
  }
}

function esc(val: string): string {
  return `'${val.replace(/'/g, "''")}'`;
}

// Start periodic flush
function startFlushTimer(): void {
  if (flushTimer) return;
  flushTimer = setInterval(() => {
    try {
      flushBuffer().catch(err => log.error('[Audit] Flush timer error:', err));
    } catch (err) {
      log.error('[Audit] Flush timer error:', err);
    }
  }, FLUSH_INTERVAL_MS);
}

// ============================================================================
// PUBLIC API
// ============================================================================

/**
 * Record an MCP tool invocation for audit purposes.
 * Non-blocking — buffers records and flushes periodically.
 */
export function recordAudit(
  requestId: string,
  toolName: string,
  apiKey: string,
  clientIp: string,
  userAgent: string,
  args: Record<string, unknown>,
  result: unknown,
  success: boolean,
  blocked: boolean,
  score: number | null,
  durationMs: number,
  errorMessage?: string,
): void {
  startFlushTimer();

  const record: AuditRecord = {
    requestId,
    toolName,
    apiKeyPrefix: apiKey.slice(0, 12) + '...',
    clientIp,
    userAgent,
    inputSummary: sanitizeInput(args),
    outputSummary: summarizeOutput(result),
    success,
    blocked,
    score,
    durationMs,
    errorMessage,
    gravitoRunId: extractGravitoRunId(result),
    decisionTraceId: extractDecisionTraceId(result),
    timestamp: Date.now(),
  };

  BUFFER.push(record);

  // Flush immediately if buffer is full
  if (BUFFER.length >= MAX_BUFFER_SIZE) {
    flushBuffer().catch(err => log.error('[Audit] Immediate flush error:', err));
  }
}

/**
 * Force flush all buffered records (call on shutdown)
 */
export async function flushAuditTrail(): Promise<void> {
  if (flushTimer) {
    clearInterval(flushTimer);
    flushTimer = null;
  }
  await flushBuffer();
}

// Types for database results
interface DbResult<T> {
  rows: T[];
}
interface StatsRow {
  total_calls: string | number;
  success_count: string | number;
  blocked_count: string | number;
  avg_duration: string | number;
}
interface ToolRow {
  tool_name: string;
  cnt: string | number;
}
interface ErrorRow {
  error_message: string;
  cnt: string | number;
}

/**
 * Get audit statistics for a time range
 */
export async function getAuditStats(sinceMs: number = 24 * 60 * 60 * 1000): Promise<{
  totalCalls: number;
  successRate: number;
  blockRate: number;
  avgDurationMs: number;
  topTools: Array<{ tool: string; count: number }>;
  topErrors: Array<{ error: string; count: number }>;
}> {
  const since = Date.now() - sinceMs;
  try {
    const db = await getDb();
    const result = await db?.execute(sql.raw(`
      SELECT 
        COUNT(*) as total_calls,
        SUM(success) as success_count,
        SUM(blocked) as blocked_count,
        AVG(duration_ms) as avg_duration
      FROM mcp_audit_trail 
      WHERE created_at > ${since}
    `));

    const toolsResult = await db?.execute(sql.raw(`
      SELECT tool_name, COUNT(*) as cnt 
      FROM mcp_audit_trail 
      WHERE created_at > ${since}
      GROUP BY tool_name 
      ORDER BY cnt DESC 
      LIMIT 10
    `));

    const errorsResult = await db?.execute(sql.raw(`
      SELECT error_message, COUNT(*) as cnt 
      FROM mcp_audit_trail 
      WHERE created_at > ${since} AND error_message IS NOT NULL
      GROUP BY error_message 
      ORDER BY cnt DESC 
      LIMIT 5
    `));

    const row = (result as unknown as DbResult<StatsRow>).rows?.[0] || {};
    const total = Number(row.total_calls) || 0;
    const successCount = Number(row.success_count) || 0;
    const blockedCount = Number(row.blocked_count) || 0;

    return {
      totalCalls: total,
      successRate: total > 0 ? successCount / total : 1,
      blockRate: total > 0 ? blockedCount / total : 0,
      avgDurationMs: Number(row.avg_duration) || 0,
      topTools: ((toolsResult as unknown as DbResult<ToolRow>).rows || []).map((r: ToolRow) => ({ tool: r.tool_name, count: Number(r.cnt) })),
      topErrors: ((errorsResult as unknown as DbResult<ErrorRow>).rows || []).map((r: ErrorRow) => ({ error: r.error_message, count: Number(r.cnt) })),
    };
  } catch (error) {
    log.error('[Audit] Failed to get stats:', error);
    return { totalCalls: 0, successRate: 1, blockRate: 0, avgDurationMs: 0, topTools: [], topErrors: [] };
  }
}

