1	/**
2	 * Nervous System Stabilizer
3	 * 
4	 * Implements the five surgical fixes identified by the Opus 4 gap analysis
5	 * to raise the nervous system score from 45→75:
6	 * 
7	 * Fix 2: Correlation ID propagation across async boundaries (+8 pts)
8	 * Fix 3: Circuit breaker state exposure in MCP responses (+5 pts)
9	 * Fix 4: Gate decision transparency in response schema (+5 pts)
10	 * Fix 5: Job management tools (list, status, cancel) (+5 pts)
11	 * Fix 6: Sync polling wrapper for MCP request-response compatibility (+7 pts)
12	 * 
13	 * Fix 1 (schema normalization) is in schema-normalizer.ts
14	 */
15	
16	import { Request } from 'express';
17	import { getCircuitBreakerSnapshot, type CircuitBreakerPrometheusSnapshot } from './circuit-breaker-metrics';
18	import { getFailClosedGate, type GateDecision, type Surface, REGULATED_SURFACES, ADVISORY_SURFACES } from './fail-closed-gate';
19	import {
20	  getJob, getAsyncQueueStats, type AsyncJob, type AsyncJobStatus,
21	} from './async-job-queue';
22	
23	// ============================================================================
24	// FIX 2: CORRELATION ID PROPAGATION
25	// ============================================================================
26	
27	const CORRELATION_HEADER = 'x-correlation-id';
28	const GRAVITO_REQUEST_HEADER = 'x-gravito-request-id';
29	
30	/**
31	 * Extract or generate a correlation ID from the request.
32	 * Propagates client-provided IDs or generates a new one.
33	 */
34	export function extractCorrelationId(req: Request): string {
35	  const clientId = req.headers[CORRELATION_HEADER] as string
36	    || req.headers[GRAVITO_REQUEST_HEADER] as string;
37	  
38	  if (clientId && typeof clientId === 'string' && clientId.length > 0) {
39	    return clientId;
40	  }
41	  
42	  // Generate a new correlation ID with timestamp prefix for sortability
43	  return `grav-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
44	}
45	
46	/**
47	 * Build correlation context that should be threaded through all async boundaries
48	 */
49	export interface CorrelationContext {
50	  correlationId: string;
51	  parentRequestId: string;
52	  toolName: string;
53	  apiKey: string;
54	  timestamp: number;
55	  clientIp: string;
56	}
57	
58	export function buildCorrelationContext(
59	  req: Request,
60	  requestId: string,
61	  toolName: string,
62	  apiKey: string
63	): CorrelationContext {
64	  return {
65	    correlationId: extractCorrelationId(req),
66	    parentRequestId: requestId,
67	    toolName,
68	    apiKey,
69	    timestamp: Date.now(),
70	    clientIp: req.ip || req.socket.remoteAddress || 'unknown',
71	  };
72	}
73	
74	/**
75	 * Headers to set on response for correlation tracing
76	 */
77	export function getCorrelationHeaders(ctx: CorrelationContext): Record<string, string> {
78	  return {
79	    [CORRELATION_HEADER]: ctx.correlationId,
80	    [GRAVITO_REQUEST_HEADER]: ctx.parentRequestId,
81	    'x-gravito-tool': ctx.toolName,
82	  };
83	}
84	
85	// ============================================================================
86	// FIX 3: CIRCUIT BREAKER STATE EXPOSURE
87	// ============================================================================
88	
89	export interface CircuitStateEnvelope {
90	  _circuit: {
91	    state: string;
92	    failure_rate: number;
93	    last_failure_time: number | null;
94	    consecutive_failures: number;
95	    total_calls: number;
96	    total_failures: number;
97	  };
98	}
99	
100	/**
101	 * Get circuit breaker state for inclusion in MCP error responses.
102	 * Returns null if circuit breaker data is unavailable.
103	 */
104	export function getCircuitStateForResponse(toolName?: string): CircuitStateEnvelope | null {
105	  try {
106	    const snapshot = getCircuitBreakerSnapshot();
107	    if (!snapshot) return null;
108	
109	    // The snapshot has a summary and breakers array
110	    const hasOpenBreaker = snapshot.summary.openBreakers > 0;
111	    const state = hasOpenBreaker ? 'OPEN' : snapshot.summary.halfOpenBreakers > 0 ? 'HALF_OPEN' : 'CLOSED';
112	    
113	    // Find the worst breaker for failure stats
114	    const worstBreaker = snapshot.breakers.reduce((worst, b) => {
115	      if (!worst || b.failures > worst.failures) return b;
116	      return worst;
117	    }, null as (typeof snapshot.breakers)[0] | null);
118	
119	    return {
120	      _circuit: {
121	        state,
122	        failure_rate: snapshot.summary.totalCalls > 0
123	          ? (snapshot.breakers.reduce((sum, b) => sum + b.failures, 0) / snapshot.summary.totalCalls)
124	          : 0,
125	        last_failure_time: worstBreaker?.lastFailure ?? null,
126	        consecutive_failures: worstBreaker?.failures ?? 0,
127	        total_calls: snapshot.summary.totalCalls,
128	        total_failures: snapshot.breakers.reduce((sum, b) => sum + b.failures, 0),
129	      },
130	    };
131	  } catch {
132	    return null;
133	  }
134	}
135	
136	/**
137	 * Enrich an error response with circuit breaker state
138	 */
139	export function enrichErrorWithCircuitState(
140	  errorResponse: Record<string, unknown>,
141	  toolName?: string
142	): Record<string, unknown> {
143	  const circuitState = getCircuitStateForResponse(toolName);
144	  if (circuitState) {
145	    return { ...errorResponse, ...circuitState };
146	  }
147	  return errorResponse;
148	}
149	
150	// ============================================================================
151	// FIX 4: GATE DECISION TRANSPARENCY
152	// ============================================================================
153	
154	export interface GateDecisionEnvelope {
155	  _governance: {
156	    requires_gate: boolean;
157	    advisory_only: boolean;
158	    surface: string;
159	    risk_level: string;
160	    regulated: boolean;
161	  };
162	}
163	
164	/**
165	 * Classify a tool call's governance requirements based on surface type.
166	 * This exposes the fail-closed gate's decision to MCP callers.
167	 */
168	export function classifyGovernanceRequirement(
169	  args: Record<string, unknown>
170	): GateDecisionEnvelope {
171	  const surfaceType = (args.surface_type || args.surfaceType || 'general') as string;
172	  const isRegulated = REGULATED_SURFACES.includes(surfaceType as Surface);
