391	  }
392	
393	  // Worker crash
394	  if (lowerMessage.includes('worker') || lowerMessage.includes('segfault') || lowerMessage.includes('killed') || lowerMessage.includes('econnreset')) {
395	    return {
396	      cause: 'worker_crash',
397	      description: 'A worker process crashed during execution. The request can be safely retried.',
398	      recoverable: true,
