/**
 * Nervous System Stabilizer
 * 
 * Implements the five surgical fixes identified by the Opus 4 gap analysis
 * to raise the nervous system score from 45→75:
 * 
 * Fix 2: Correlation ID propagation across async boundaries (+8 pts)
 * Fix 3: Circuit breaker state exposure in MCP responses (+5 pts)
 * Fix 4: Gate decision transparency in response schema (+5 pts)
 * Fix 5: Job management tools (list, status, cancel) (+5 pts)
 * Fix 6: Sync polling wrapper for MCP request-response compatibility (+7 pts)
 * 
 * Fix 1 (schema normalization) is in schema-normalizer.ts
 */

import { Request } from 'express';
import { getCircuitBreakerSnapshot, type CircuitBreakerPrometheusSnapshot } from './circuit-breaker-metrics';
import { getFailClosedGate, type GateDecision, type Surface, REGULATED_SURFACES, ADVISORY_SURFACES } from './fail-closed-gate';
import {
  getJob, getAsyncQueueStats, type AsyncJob, type AsyncJobStatus,
} from './async-job-queue';

// ============================================================================
// FIX 2: CORRELATION ID PROPAGATION
// ============================================================================

const CORRELATION_HEADER = 'x-correlation-id';
const GRAVITO_REQUEST_HEADER = 'x-gravito-request-id';

/**
 * Extract or generate a correlation ID from the request.
 * Propagates client-provided IDs or generates a new one.
 */
export function extractCorrelationId(req: Request): string {
  const clientId = req.headers[CORRELATION_HEADER] as string
    || req.headers[GRAVITO_REQUEST_HEADER] as string;

  if (clientId && typeof clientId === 'string' && clientId.length > 0) {
    return clientId;
  }

  // Generate a new correlation ID with timestamp prefix for sortability
  return `grav-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

/**
 * Build correlation context that should be threaded through all async boundaries
 */
export interface CorrelationContext {
  correlationId: string;
  parentRequestId: string;
  toolName: string;
  apiKey: string;
  timestamp: number;
  clientIp: string;
}

export function buildCorrelationContext(
  req: Request,
  requestId: string,
  toolName: string,
  apiKey: string
): CorrelationContext {
  return {
    correlationId: extractCorrelationId(req),
    parentRequestId: requestId,
    toolName,
    apiKey,
    timestamp: Date.now(),
    clientIp: req.ip || req.socket.remoteAddress || 'unknown',
  };
}

/**
 * Headers to set on response for correlation tracing
 */
export function getCorrelationHeaders(ctx: CorrelationContext): Record<string, string> {
  return {
    [CORRELATION_HEADER]: ctx.correlationId,
    [GRAVITO_REQUEST_HEADER]: ctx.parentRequestId,
    'x-gravito-tool': ctx.toolName,
  };
}

// ============================================================================
// FIX 3: CIRCUIT BREAKER STATE EXPOSURE
// ============================================================================

export interface CircuitStateEnvelope {
  _circuit: {
    state: string;
    failure_rate: number;
    last_failure_time: number | null;
    consecutive_failures: number;
    total_calls: number;
    total_failures: number;
  };
}

/**
 * Get circuit breaker state for inclusion in MCP error responses.
 * Returns null if circuit breaker data is unavailable.
 */
export function getCircuitStateForResponse(toolName?: string): CircuitStateEnvelope | null {
  try {
    const snapshot = getCircuitBreakerSnapshot();
    if (!snapshot) return null;

    // The snapshot has a summary and breakers array
    const hasOpenBreaker = snapshot.summary.openBreakers > 0;
    const state = hasOpenBreaker ? 'OPEN' : snapshot.summary.halfOpenBreakers > 0 ? 'HALF_OPEN' : 'CLOSED';

    // Find the worst breaker for failure stats
    const worstBreaker = snapshot.breakers.reduce((worst, b) => {
      if (!worst || b.failures > worst.failures) return b;
      return worst;
    }, null as (typeof snapshot.breakers)[0] | null);

    return {
      _circuit: {
        state,
        failure_rate: snapshot.summary.totalCalls > 0
          ? (snapshot.breakers.reduce((sum, b) => sum + b.failures, 0) / snapshot.summary.totalCalls)
          : 0,
        last_failure_time: worstBreaker?.lastFailure ?? null,
        consecutive_failures: worstBreaker?.failures ?? 0,
        total_calls: snapshot.summary.totalCalls,
        total_failures: snapshot.breakers.reduce((sum, b) => sum + b.failures, 0),
      },
    };
  } catch {
    return null;
  }
}

/**
 * Enrich an error response with circuit breaker state
 */
export function enrichErrorWithCircuitState(
  errorResponse: Record<string, unknown>,
  toolName?: string
): Record<string, unknown> {
  const circuitState = getCircuitStateForResponse(toolName);
  if (circuitState) {
    return { ...errorResponse, ...circuitState };
  }
  return errorResponse;
}

// ============================================================================
// FIX 4: GATE DECISION TRANSPARENCY
// ============================================================================

export interface GateDecisionEnvelope {
  _governance: {
    requires_gate: boolean;
    advisory_only: boolean;
    surface: string;
    risk_level: string;
    regulated: boolean;
  };
}

/**
 * Classify a tool call's governance requirements based on surface type.
 * This exposes the fail-closed gate's decision to MCP callers.
 */
export function classifyGovernanceRequirement(
  args: Record<string, unknown>
): GateDecisionEnvelope {
  const surfaceType = (args.surface_type || args.surfaceType || 'general') as string;
  const isRegulated = REGULATED_SURFACES.includes(surfaceType as Surface);
  const isAdvisory = ADVISORY_SURFACES.includes(surfaceType as Surface);

  return {
    _governance: {
      requires_gate: isRegulated,
      advisory_only: isAdvisory,
      surface: surfaceType,
      risk_level: isRegulated ? 'high' : isAdvisory ? 'medium' : 'low',
      regulated: isRegulated,
    },
  };
}

/**
 * Enrich a successful response with governance metadata
 */
export function enrichResponseWithGovernance(
  response: Record<string, unknown>,
  args: Record<string, unknown>
): Record<string, unknown> {
  const governance = classifyGovernanceRequirement(args);
  return { ...response, ...governance };
}

// ============================================================================
// FIX 5: JOB MANAGEMENT — LIST, STATUS, CANCEL
// ============================================================================

// We need access to the internal jobs Map — export helper functions from async-job-queue
// For now, use getJob and getAsyncQueueStats which are already exported

export interface JobListResult {
  jobs: Array<{
    id: string;
    tool: string;
    status: AsyncJobStatus;
    created_at: number;
    started_at?: number;
    completed_at?: number;
    elapsed_ms?: number;
    has_result: boolean;
    has_webhook: boolean;
  }>;
  total: number;
  filtered: number;
  queue_stats: ReturnType<typeof getAsyncQueueStats>;
}

/**
 * List jobs for a given API key with optional status filter.
 * Note: This requires the async-job-queue to expose a listJobs function.
 * We add it as an extension point here.
 */
export function formatJobForList(job: AsyncJob): JobListResult['jobs'][0] {
  return {
    id: job.id,
    tool: job.toolName,
    status: job.status,
    created_at: job.createdAt,
    started_at: job.startedAt,
    completed_at: job.completedAt,
    elapsed_ms: job.completedAt ? job.completedAt - job.createdAt : 
                job.startedAt ? Date.now() - job.startedAt : undefined,
    has_result: job.status === 'completed' && !!job.result,
    has_webhook: !!job.webhook,
  };
}

// ============================================================================
// FIX 6: SYNC POLLING WRAPPER (reviewContentAndWait)
// ============================================================================

const SYNC_POLL_TIMEOUT_MS = 20_000; // 20 seconds max wait
const SYNC_POLL_INTERVAL_MS = 500;   // Check every 500ms

export interface SyncPollResult {
  success: boolean;
  result?: unknown;
  error?: string;
  elapsed_ms: number;
  was_async: boolean;
  job_id?: string;
}

/**
 * Wait for an async job to complete within a timeout.
 * This bridges the MCP request-response model with the async job queue.
 * 
 * Used by the MCP handler to transparently convert async tools to sync
 * when the expected runtime is under 20 seconds.
 */
export async function waitForJobCompletion(
  jobId: string,
  apiKey: string,
  timeoutMs: number = SYNC_POLL_TIMEOUT_MS
): Promise<SyncPollResult> {
  const start = Date.now();

  while (Date.now() - start < timeoutMs) {
    const job = getJob(jobId, apiKey);

    if (!job) {
      return {
        success: false,
        error: `Job ${jobId} not found or access denied`,
        elapsed_ms: Date.now() - start,
        was_async: true,
        job_id: jobId,
      };
    }

    if (job.status === 'completed') {
      return {
        success: true,
        result: job.result,
        elapsed_ms: Date.now() - start,
        was_async: true,
        job_id: jobId,
      };
    }

    if (job.status === 'failed') {
      return {
        success: false,
        error: job.error || 'Job failed',
        elapsed_ms: Date.now() - start,
        was_async: true,
        job_id: jobId,
      };
    }

    if (job.status === 'expired') {
      return {
        success: false,
        error: 'Job expired before completion',
        elapsed_ms: Date.now() - start,
        was_async: true,
        job_id: jobId,
      };
    }

    // Still pending/running — wait and poll again
    await new Promise(resolve => setTimeout(resolve, SYNC_POLL_INTERVAL_MS));
  }

  // Timeout — return partial result
  return {
    success: false,
    error: `Sync poll timeout after ${timeoutMs}ms. Job ${jobId} is still processing. Use async polling at /api/mcp/jobs/${jobId}`,
    elapsed_ms: Date.now() - start,
    was_async: true,
    job_id: jobId,
  };
}

// ============================================================================
// 503 CAUSE CLASSIFICATION
// ============================================================================

export type ServiceUnavailableCause = 
  | 'circuit_breaker_open'
  | 'worker_crash'
  | 'timeout_cascade'
  | 'memory_pressure'
  | 'rate_limit_exhausted'
  | 'unknown';

export interface ClassifiedError {
  cause: ServiceUnavailableCause;
  description: string;
  recoverable: boolean;
  retry_after_ms: number;
  circuit_state?: string;
}

/**
 * Classify the root cause of a 503 error for structured error reporting.
 */
export function classify503Cause(
  error: Error | string,
  toolName?: string
): ClassifiedError {
  const message = error instanceof Error ? error.message : error;
  const lowerMessage = message.toLowerCase();

  // Check circuit breaker state
  try {
    const snapshot = getCircuitBreakerSnapshot();
    // @ts-ignore — TS2339 interface drift
    if (snapshot?.state === 'OPEN') {
      return {
        cause: 'circuit_breaker_open',
        description: `Circuit breaker is OPEN for tool group. Too many recent failures (${(snapshot as unknown as { consecutiveFailures: number }).consecutiveFailures} consecutive).`,
        recoverable: true,
        retry_after_ms: 30_000, // Wait for half-open transition
        circuit_state: 'OPEN',
      };
    }
  } catch { /* ignore */ }

  // Memory pressure
  if (lowerMessage.includes('heap') || lowerMessage.includes('out of memory') || lowerMessage.includes('allocation failed')) {
    return {
      cause: 'memory_pressure',
      description: 'Server is under memory pressure. Reduce request complexity or retry later.',
      recoverable: true,
      retry_after_ms: 60_000,
    };
  }

  // Timeout cascade
  if (lowerMessage.includes('timeout') || lowerMessage.includes('timed out') || lowerMessage.includes('deadline exceeded')) {
    return {
      cause: 'timeout_cascade',
      description: `Tool execution timed out. The server may be under heavy load.`,
      recoverable: true,
      retry_after_ms: 10_000,
    };
  }

  // Worker crash
  if (lowerMessage.includes('worker') || lowerMessage.includes('segfault') || lowerMessage.includes('killed') || lowerMessage.includes('econnreset')) {
    return {
      cause: 'worker_crash',
      description: 'A worker process crashed during execution. The request can be safely retried.',
      recoverable: true,
      retry_after_ms: 5_000,
    };
  }

  // Rate limit
  if (lowerMessage.includes('rate limit') || lowerMessage.includes('too many requests')) {
    return {
      cause: 'rate_limit_exhausted',
      description: 'Rate limit exhausted across all tiers.',
      recoverable: true,
      retry_after_ms: 60_000,
    };
  }

  // Unknown
  return {
    cause: 'unknown',
    description: `Service unavailable: ${message.slice(0, 200)}`,
    recoverable: true,
    retry_after_ms: 15_000,
  };
}

/**
 * Build a structured 503 response with classified cause
 */
export function build503Response(
  error: Error | string,
  toolName?: string,
  correlationId?: string
): Record<string, unknown> {
  const classified = classify503Cause(error, toolName);
  const circuitState = getCircuitStateForResponse(toolName);

  return {
    success: false,
    error: 'SERVICE_UNAVAILABLE',
    error_code: '503',
    cause: classified.cause,
    description: classified.description,
    recoverable: classified.recoverable,
    retry_after_ms: classified.retry_after_ms,
    tool: toolName,
    correlation_id: correlationId,
    ...(circuitState || {}),
    timestamp: Date.now(),
  };
}

// ============================================================================
// COMBINED RESPONSE ENRICHMENT
// ============================================================================

/**
 * Enrich any MCP tool response with nervous system metadata:
 * - Correlation ID
 * - Circuit breaker state (on errors)
 * - Governance classification
 */
export function enrichMCPResponse(
  response: Record<string, unknown>,
  ctx: {
    correlationId?: string;
    toolName?: string;
    args?: Record<string, unknown>;
    isError?: boolean;
  }
): Record<string, unknown> {
  let enriched = { ...response };

  // Always add correlation ID
  if (ctx.correlationId) {
    enriched._correlation_id = ctx.correlationId;
  }

  // Add circuit state on errors
  if (ctx.isError) {
    enriched = enrichErrorWithCircuitState(enriched, ctx.toolName);
  }

  // Add governance classification if args contain surface info
  if (ctx.args && (ctx.args.surface_type || ctx.args.surfaceType)) {
    enriched = enrichResponseWithGovernance(enriched, ctx.args);
  }

  return enriched;
}

