/**
 * MCP Usage Logging & Governance Events
 * 
 * Handles usage tracking, token estimation, and real-time governance
 * event emission for the MCP handler.
 */

import { createLogger } from '../_core/logger';

const log = createLogger('mcp');

// ============================================================================
// TOKEN ESTIMATION
// ============================================================================

/**
 * Rough token estimate: ~4 chars per token for English text.
 */
export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

// ============================================================================
// USAGE LOGGING
// ============================================================================

interface UsageEntry {
  apiKey?: string;
  ipAddress?: string;
  toolName: string;
  method: string;
  success: boolean;
  errorMessage?: string;
  responseTimeMs: number;
  estimatedInputTokens?: number;
  estimatedOutputTokens?: number;
  userAgent?: string;
}

const usageLog: UsageEntry[] = [];
const MAX_USAGE_LOG = 10000;

/**
 * Log a usage entry for billing/analytics.
 */
export function logUsage(entry: UsageEntry): void {
  usageLog.push(entry);
  if (usageLog.length > MAX_USAGE_LOG) {
    usageLog.splice(0, usageLog.length - MAX_USAGE_LOG);
  }
}

/**
 * Get usage stats since a given date.
 */
export async function getUsageStats(since: Date): Promise<{
  total_requests: number;
  successful: number;
  failed: number;
  total_input_tokens: number;
  total_output_tokens: number;
  avg_response_time_ms: number;
  tools_used: Record<string, number>;
}> {
  const sinceMs = since.getTime();
  // Filter entries by timestamp (approximate — we don't store timestamp, use responseTimeMs as proxy)
  // In production, this would query the database
  const recent = usageLog; // For now, return all

  const tools: Record<string, number> = {};
  let totalInput = 0;
  let totalOutput = 0;
  let totalTime = 0;
  let successful = 0;
  let failed = 0;

  for (const entry of recent) {
    tools[entry.toolName] = (tools[entry.toolName] || 0) + 1;
    totalInput += entry.estimatedInputTokens || 0;
    totalOutput += entry.estimatedOutputTokens || 0;
    totalTime += entry.responseTimeMs;
    if (entry.success) successful++;
    else failed++;
  }

  return {
    total_requests: recent.length,
    successful,
    failed,
    total_input_tokens: totalInput,
    total_output_tokens: totalOutput,
    avg_response_time_ms: recent.length > 0 ? Math.round(totalTime / recent.length) : 0,
    tools_used: tools,
  };
}

// ============================================================================
// GOVERNANCE EVENTS (real-time)
// ============================================================================

interface GovernanceEvent {
  type: 'block' | 'approval' | 'error';
  source: string;
  tool: string;
  score?: number;
  blocked: boolean;
  details: string;
  apiKeyPrefix?: string;
  durationMs?: number;
  timestamp: string;
}

type GovernanceEventListener = (event: GovernanceEvent) => void;
const listeners: GovernanceEventListener[] = [];

/**
 * Emit a governance event (block, approval, or error).
 */
export function emitGovernanceEvent(event: Omit<GovernanceEvent, 'timestamp'>): void {
  const fullEvent: GovernanceEvent = {
    ...event,
    timestamp: new Date().toISOString(),
  };

  for (const listener of listeners) {
    try {
      listener(fullEvent);
    } catch (e) {
      log.warn('[MCP Usage] Governance event listener error:', e);
    }
  }
}

/**
 * Subscribe to governance events.
 */
export function onGovernanceEvent(listener: GovernanceEventListener): () => void {
  listeners.push(listener);
  return () => {
    const idx = listeners.indexOf(listener);
    if (idx >= 0) listeners.splice(idx, 1);
  };
}

/**
 * Detect if a response indicates a block.
 */
export function isBlockedResponse(responseText: string): boolean {
  return responseText.includes('"block_release":true') || responseText.includes('"blocked":true');
}

/**
 * Extract score from a response.
 */
export function extractScore(responseText: string): number | undefined {
  const match = responseText.match(/"score"\s*:\s*(\d+)/);
  return match ? parseInt(match[1]) : undefined;
}

