1	/**
2	 * Gate Enforcement Layer
3	 * 
4	 * Mechanically enforces fail-closed governance at the MCP handler level.
5	 * This is the missing enforcement point — the fail-closed-gate module defines
6	 * the rules, but they were only applied in the content generation middleware,
7	 * not at the tool execution boundary.
8	 * 
9	 * This module:
10	 * 1. Pre-checks every tool call against the gate before execution
11	 * 2. Blocks regulated-surface tools without approval tokens
12	 * 3. Adds governance_mode field to every response (enforced | advisory | passthrough)
13	 * 4. Tracks degraded mode transitions when Gravito is unavailable
14	 * 5. Provides explicit requiresGate boolean in response schema
15	 */
16	
17	import {
18	  getFailClosedGate,
19	  type Surface,
20	  type GateDecision,
21	  REGULATED_SURFACES,
22	  ADVISORY_SURFACES,
23	} from './fail-closed-gate';
24	// Lazy imports to avoid circular dependency with telemetry-streams → governed-generate chain
25	let _recordDegradedMode: ((surfaceId: string, productId: string, reason: string) => void) | null = null;
26	let _recordDegradedRecovery: (() => void) | null = null;
27	
28	async function loadTelemetry() {
29	  if (!_recordDegradedMode) {
30	    try {
31	      const mod = await import('../governance/telemetry-streams');
32	      _recordDegradedMode = mod.recordDegradedMode;
33	      _recordDegradedRecovery = mod.recordDegradedRecovery;
34	    } catch {
35	      // Telemetry not available — degrade gracefully
36	    }
37	  }
38	}
39	
40	// ============================================================================
41	// TYPES
42	// ============================================================================
43	
44	export type GovernanceMode = 'enforced' | 'advisory' | 'passthrough' | 'degraded';
45	
46	export interface GateEnforcementResult {
47	  /** Whether the tool call is allowed to proceed */
48	  allowed: boolean;
49	  /** The governance mode applied to this call */
50	  governance_mode: GovernanceMode;
51	  /** Whether this tool/surface combination requires a governance gate */
52	  requires_gate: boolean;
53	  /** Whether the gate check was advisory only (warn but allow) */
54	  advisory_only: boolean;
55	  /** The detected or provided surface type */
56	  surface: Surface;
57	  /** Risk level assessment */
58	  risk_level: 'low' | 'medium' | 'high' | 'critical';
59	  /** Human-readable reason for the decision */
60	  reason: string;
61	  /** Gravito invocation ID for audit trail */
62	  gravito_invocation_id: string;
63	  /** If blocked, what the caller should do */
64	  remediation?: string;
65	  /** Gate decision details (for audit) */
66	  gate_decision?: GateDecision;
67	}
68	
69	export interface GateEnforcementConfig {
70	  /** Whether enforcement is active (default: true) */
71	  enabled: boolean;
72	  /** Whether to allow degraded mode when Gravito is unavailable (default: true for advisory, false for regulated) */
73	  allowDegradedMode: boolean;
74	  /** Maximum time to wait for gate check before degrading (ms) */
75	  gateTimeoutMs: number;
76	  /** Whether to log all gate decisions */
77	  logAllDecisions: boolean;
78	}
79	
80	// ============================================================================
81	// TOOL-SURFACE MAPPING
82	// ============================================================================
83	
84	/**
85	 * Maps tool names to their primary surface type.
86	 * Tools not in this map default to 'general'.
87	 * This is the canonical source of truth for which tools touch which surfaces.
88	 */
89	const TOOL_SURFACE_MAP: Record<string, Surface> = {
90	  // Medical surface tools
91	  'reviewContent': 'general', // reviewContent is generic — surface detected from content
92	  'generateGovernedContent': 'general', // surface detected from content
93	  
94	  // Financial surface tools
95	  'governance_calculate_goal_score': 'compliance',
96	  'governance_get_goal_function': 'compliance',
97	  
98	  // Compliance tools
99	  'governanceAudit': 'compliance',
100	  'governancePlayground': 'general',
101	  
102	  // Content generation (surface from content)
103	  'analyzeEmotionalGeometry': 'general',
104	  'surfaceIntelligence': 'general',
105	  'creativePartner': 'general',
106	};
107	
108	/**
109	 * Tools that are exempt from gate enforcement.
110	 * These are infrastructure/diagnostic tools that don't produce governed content.
111	 */
112	const EXEMPT_TOOLS = new Set([
113	  'list_tools',
114	  'get_tool_schema',
115	  'health_check',
116	  'get_metrics',
117	  'get_audit_log',
118	  'get_rate_limit_status',
119	  // Governance tools are exempt — they ARE the governance layer, can't gate themselves
120	  'reviewContent',
121	  'governanceAudit',
122	  'verifyClaim',
123	  'checkCompliance',
124	  'getDecisionTrace',
125	  'classifyClaims',
126	  'detectForbiddenLanguage',
127	  'enforceBrandVoice',
128	  'suggestRefinement',
129	  'generateVariants',
130	  'composeEmail',
131	  'getCapabilities',
132	  'toolHealth',
133	  'runGravito',
134	  'fullMessagingAnalysis',
135	  'analyzeBehavior',
136	  // Enhanced tools — Claude-powered implementations for Stylier integration
137	  'reviewArtifact',
138	  'surfaceIntelTrackEvent',
139	  'surfaceIntelGetConversionBlockers',
140	  'detectMoment',
141	  'predictLTV',
142	  'predictIntent',
143	  'analyzeContent',
144	  // Messaging analysis tools — these analyze existing content, they don't generate regulated content
145	  'analyzePositioning',
146	  'analyzeGravitas',
147	  'analyzeBuyerObjections',
148	  'analyzeCompetitiveDifferentiation',
149	  'analyzeCrossChannelCoherence',
150	  'analyzeFearUrgency',
151	  'analyzeJourneyCoherence',
152	  'analyzePromiseProductAlignment',
153	  'checkCriticalAlignment',
154	  'checkCriticalObjectionGaps',
155	  'checkFeatureStartupLanguage',
156	  'checkGenericCopy',
157	  'checkSafeButForgettable',
158	  'compareMessaging',
159	  'comprehensiveGapAnalysis',
160	  'detectDrift',
161	  'getPreTractionMessaging',
162	  'getTrustRecommendations',
163	  'predictABTestWinner',
164	  'quickABCompare',
165	  'quickCompareHeadlines',
166	  'validateBusinessTruth',
167	  'clarifyIntent',
168	  'evaluateExperimentOutcome',
169	  // Baseline/experiment management tools — CRUD operations, not content generation
170	  'getLatestBaseline',
171	  'getBaselineHistory',
172	  'deactivateBaseline',
173	  'createExperimentFromPatch',
174	  'linkPatchToExperiment',
175	  'promoteWinner',
176	  'getPatchOutcome',
177	  'recordFeedback',
178	  'registerApprovedClaim',
179	  'calculateAttribution',
