182	  'createAuditSchedule',
183	  'updateAuditSchedule',
184	  'deleteAuditSchedule',
185	  'runScheduledAuditNow',
186	  'listBreakGlass',
187	  'breakGlass',
188	  'breakGlassDrill',
189	  'runEscalation',
190	  'agentRuntimeValidateSite',
191	]);
192	
193	// ============================================================================
194	// DEFAULT CONFIG
195	// ============================================================================
196	
197	const DEFAULT_CONFIG: GateEnforcementConfig = {
198	  enabled: true,
199	  allowDegradedMode: true,
200	  gateTimeoutMs: 5000,
201	  logAllDecisions: true,
202	};
203	
204	let _config: GateEnforcementConfig = { ...DEFAULT_CONFIG };
205	let _isDegraded = false;
206	let _degradedSince: number | null = null;
207	let _degradedReason: string | null = null;
208	
209	// ============================================================================
210	// CORE ENFORCEMENT
211	// ============================================================================
212	
213	/**
214	 * Pre-execution gate check for MCP tool calls.
215	 * 
216	 * This is the mechanical enforcement point that was missing.
217	 * Call this BEFORE executing any tool via the MCP handler.
218	 * 
219	 * Decision matrix:
220	 * - Exempt tool → passthrough (always allowed)
221	 * - Regulated surface → enforced (blocked without approval token)
222	 * - Advisory surface → advisory (allowed with warning)
223	 * - General surface → passthrough (allowed)
224	 * - Degraded mode → depends on surface (regulated = blocked, advisory/general = allowed with warning)
225	 */
226	export function enforceGate(
227	  toolName: string,
228	  args: Record<string, unknown>,
229	  options?: {
230	    surface?: Surface;
231	    approvalToken?: string;
232	    content?: string;
233	  }
234	): GateEnforcementResult {
235	  const gate = getFailClosedGate();
236	  const shortName = toolName.replace('gravito.', '');
237	  
238	  // Exempt tools bypass gate entirely
239	  if (EXEMPT_TOOLS.has(shortName)) {
240	    return {
241	      allowed: true,
242	      governance_mode: 'passthrough',
243	      requires_gate: false,
244	      advisory_only: false,
245	      surface: 'general',
246	      risk_level: 'low',
247	      reason: `Tool \"${shortName}\" is exempt from governance gate`,
248	      gravito_invocation_id: `exempt_${Date.now()}`,
249	    };
250	  }
251	
252	  // Determine surface from: explicit option > args.surface_type > content detection > tool map > 'general'
253	  let surface: Surface = 'general';
254	  
255	  if (options?.surface) {
256	    // 1. Explicit option override (highest priority)
257	    surface = options.surface;
258	  } else {
259	    // 2. Check args.surface_type / args.surfaceType (explicit caller intent)
260	    const argSurface = (args.surface_type || args.surfaceType) as string | undefined;
261	    if (argSurface && isValidSurface(argSurface)) {
262	      surface = argSurface as Surface;
263	    } else {
264	      // 3. Content-based detection from args content fields
265	      const contentFields = ['content', 'text', 'message', 'body', 'prompt', 'input'];
266	      for (const field of contentFields) {
267	        if (typeof args[field] === 'string' && (args[field] as string).length > 10) {
268	          const detected = gate.detectSurface(args[field] as string);
269	          if (detected !== 'general') {
270	            surface = detected;
271	            break;
272	          }
273	        }
274	      }
275	      // 4. Also try options.content if provided
276	      if (surface === 'general' && options?.content) {
277	        surface = gate.detectSurface(options.content);
278	      }
279	      // 5. Fall back to tool map (only if it maps to a non-general surface)
280	      if (surface === 'general' && TOOL_SURFACE_MAP[shortName] && TOOL_SURFACE_MAP[shortName] !== 'general') {
281	        surface = TOOL_SURFACE_MAP[shortName];
282	      }
283	    }
284	  }
285	
286	  const isRegulated = REGULATED_SURFACES.includes(surface);
287	  const isAdvisory = ADVISORY_SURFACES.includes(surface);
288	  const riskLevel = gate.assessRiskLevel(surface, shortName);
289	
290	  // Check if system is in degraded mode
291	  if (_isDegraded) {
292	    if (isRegulated) {
293	      // Regulated surface in degraded mode = BLOCKED (fail-closed)
294	      return {
295	        allowed: false,
296	        governance_mode: 'degraded',
297	        requires_gate: true,
298	        advisory_only: false,
299	        surface,
300	        risk_level: riskLevel,
301	        reason: `System is in degraded mode (since ${new Date(_degradedSince || 0).toISOString()}). Regulated surface \"${surface}\" requires full governance — blocked until recovery.`,
302	        gravito_invocation_id: `degraded_${Date.now()}`,
303	        remediation: 'Wait for governance service recovery or contact system administrator.',
304	      };
305	    }
306	    // Advisory/general in degraded mode = allowed with warning
307	    return {
308	      allowed: true,
309	      governance_mode: 'degraded',
310	      requires_gate: isAdvisory,
311	      advisory_only: isAdvisory,
312	      surface,
313	      risk_level: riskLevel,
314	      reason: `System is in degraded mode. ${isAdvisory ? 'Advisory' : 'General'} surface \"${surface}\" allowed with reduced governance.`,
315	      gravito_invocation_id: `degraded_${Date.now()}`,
316	    };
317	  }
318	
319	  // Run the gate check
320	  const gateDecision = gate.checkGate(shortName, options?.content || JSON.stringify(args), surface);
321	
322	  // If gate blocks and caller has an approval token, validate it
323	  if (!gateDecision.allowed && options?.approvalToken) {
324	    const validation = gate.validateToken(options.approvalToken, shortName);
325	    if (validation.valid) {
326	      return {
327	        allowed: true,
328	        governance_mode: 'enforced',
329	        requires_gate: true,
330	        advisory_only: false,
331	        surface,
332	        risk_level: riskLevel,
333	        reason: `Approved via token ${options.approvalToken.substring(0, 12)}...`,
334	        gravito_invocation_id: validation.gravitoInvocationId,
335	        gate_decision: gateDecision,
336	      };
337	    }
338	  }
339	
340	  // Gate blocked without valid token
341	  if (!gateDecision.allowed) {
342	    return {
343	      allowed: false,
344	      governance_mode: 'enforced',
345	      requires_gate: true,
346	      advisory_only: false,
347	      surface,
348	      risk_level: riskLevel,
349	      reason: gateDecision.reason,
350	      gravito_invocation_id: gateDecision.gravitoInvocationId,
351	      remediation: 'Call gravito.reviewContent first to obtain an approval token, then pass it as approval_token in the tool args.',
352	      gate_decision: gateDecision,
353	    };
354	  }
355	
356	  // Gate allowed — determine mode
357	  const governanceMode: GovernanceMode = isRegulated ? 'enforced' : isAdvisory ? 'advisory' : 'passthrough';
358	
359	  return {
360	    allowed: true,
361	    governance_mode: governanceMode,
362	    requires_gate: isRegulated,
363	    advisory_only: isAdvisory,
364	    surface,
365	    risk_level: riskLevel,
366	    reason: gateDecision.reason,
367	    gravito_invocation_id: gateDecision.gravitoInvocationId,
368	    gate_decision: gateDecision,
369	  };
370	}
371	
372	// ============================================================================
373	// DEGRADED MODE MANAGEMENT
374	// ============================================================================
375	
376	/**
377	 * Enter degraded mode when Gravito governance is unavailable.
378	 * In degraded mode:
379	 * - Regulated surfaces are BLOCKED (fail-closed)
380	 * - Advisory surfaces are ALLOWED with warning
381	 * - General surfaces are ALLOWED
382	 */
383	export function enterDegradedMode(reason: string): void {
384	  if (!_isDegraded) {
385	    _isDegraded = true;
386	    _degradedSince = Date.now();
387	    _degradedReason = reason;
388	    loadTelemetry()
389	      .then(() => _recordDegradedMode?.("system", "mcp", reason))
390	      .catch(() => {
391	        /* telemetry load is best-effort */
392	      });
393	  }
394	}
395	
396	/**
397	 * Exit degraded mode when Gravito governance recovers.
398	 */
399	export function exitDegradedMode(): void {
400	  if (_isDegraded) {
401	    _isDegraded = false;
402	    _degradedSince = null;
403	    _degradedReason = null;
404	    loadTelemetry()
405	      .then(() => _recordDegradedRecovery?.())
406	      .catch(() => {
407	        /* telemetry load is best-effort */
408	      });
409	  }
410	}
411	
412	/**
413	 * Get current degraded mode status.
414	 */
415	export function getDegradedStatus(): {
416	  isDegraded: boolean;
417	  since: number | null;
418	  reason: string | null;
419	  durationMs: number | null;
420	} {
421	  return {
422	    isDegraded: _isDegraded,
423	    since: _degradedSince,
424	    reason: _degradedReason,
425	    durationMs: _isDegraded && _degradedSince ? Date.now() - _degradedSince : null,
426	  };
427	}
428	
429	// ============================================================================
430	// RESPONSE ENRICHMENT
431	// ============================================================================
432	
433	/**
434	 * Build the governance envelope to attach to every MCP response.
435	 * This makes the gate decision explicit and machine-readable.
436	 */
437	export function buildGovernanceEnvelope(enforcement: GateEnforcementResult): Record<string, unknown> {
438	  return {
439	    _governance: {
440	      mode: enforcement.governance_mode,
