/**
 * Gate Enforcement Layer
 * 
 * Mechanically enforces fail-closed governance at the MCP handler level.
 * This is the missing enforcement point — the fail-closed-gate module defines
 * the rules, but they were only applied in the content generation middleware,
 * not at the tool execution boundary.
 * 
 * This module:
 * 1. Pre-checks every tool call against the gate before execution
 * 2. Blocks regulated-surface tools without approval tokens
 * 3. Adds governance_mode field to every response (enforced | advisory | passthrough)
 * 4. Tracks degraded mode transitions when Gravito is unavailable
 * 5. Provides explicit requiresGate boolean in response schema
 */

import {
  getFailClosedGate,
  type Surface,
  type GateDecision,
  REGULATED_SURFACES,
  ADVISORY_SURFACES,
} from './fail-closed-gate';
// Lazy imports to avoid circular dependency with telemetry-streams → governed-generate chain
let _recordDegradedMode: ((surfaceId: string, productId: string, reason: string) => void) | null = null;
let _recordDegradedRecovery: (() => void) | null = null;

async function loadTelemetry() {
  if (!_recordDegradedMode) {
    try {
      const mod = await import('../governance/telemetry-streams');
      _recordDegradedMode = mod.recordDegradedMode;
      _recordDegradedRecovery = mod.recordDegradedRecovery;
    } catch {
      // Telemetry not available — degrade gracefully
    }
  }
}

// ============================================================================
// TYPES
// ============================================================================

export type GovernanceMode = 'enforced' | 'advisory' | 'passthrough' | 'degraded';

export interface GateEnforcementResult {
  /** Whether the tool call is allowed to proceed */
  allowed: boolean;
  /** The governance mode applied to this call */
  governance_mode: GovernanceMode;
  /** Whether this tool/surface combination requires a governance gate */
  requires_gate: boolean;
  /** Whether the gate check was advisory only (warn but allow) */
  advisory_only: boolean;
  /** The detected or provided surface type */
  surface: Surface;
  /** Risk level assessment */
  risk_level: 'low' | 'medium' | 'high' | 'critical';
  /** Human-readable reason for the decision */
  reason: string;
  /** Gravito invocation ID for audit trail */
  gravito_invocation_id: string;
  /** If blocked, what the caller should do */
  remediation?: string;
  /** Gate decision details (for audit) */
  gate_decision?: GateDecision;
}

export interface GateEnforcementConfig {
  /** Whether enforcement is active (default: true) */
  enabled: boolean;
  /** Whether to allow degraded mode when Gravito is unavailable (default: true for advisory, false for regulated) */
  allowDegradedMode: boolean;
  /** Maximum time to wait for gate check before degrading (ms) */
  gateTimeoutMs: number;
  /** Whether to log all gate decisions */
  logAllDecisions: boolean;
}

// ============================================================================
// TOOL-SURFACE MAPPING
// ============================================================================

/**
 * Maps tool names to their primary surface type.
 * Tools not in this map default to 'general'.
 * This is the canonical source of truth for which tools touch which surfaces.
 */
const TOOL_SURFACE_MAP: Record<string, Surface> = {
  // Medical surface tools
  'reviewContent': 'general', // reviewContent is generic — surface detected from content
  'generateGovernedContent': 'general', // surface detected from content

  // Financial surface tools
  'governance_calculate_goal_score': 'compliance',
  'governance_get_goal_function': 'compliance',

  // Compliance tools
  'governanceAudit': 'compliance',
  'governancePlayground': 'general',

  // Content generation (surface from content)
  'analyzeEmotionalGeometry': 'general',
  'surfaceIntelligence': 'general',
  'creativePartner': 'general',
};

/**
 * Tools that are exempt from gate enforcement.
 * These are infrastructure/diagnostic tools that don't produce governed content.
 */
const EXEMPT_TOOLS = new Set([
  'list_tools',
  'get_tool_schema',
  'health_check',
  'get_metrics',
  'get_audit_log',
  'get_rate_limit_status',
  // Governance tools are exempt — they ARE the governance layer, can't gate themselves
  'reviewContent',
  'governanceAudit',
  'verifyClaim',
  'checkCompliance',
  'getDecisionTrace',
  'classifyClaims',
  'detectForbiddenLanguage',
  'enforceBrandVoice',
  'suggestRefinement',
  'generateVariants',
  'composeEmail',
  'getCapabilities',
  'toolHealth',
  'runGravito',
  'fullMessagingAnalysis',
  'analyzeBehavior',
  // Enhanced tools — Claude-powered implementations for Stylier integration
  'reviewArtifact',
  'surfaceIntelTrackEvent',
  'surfaceIntelGetConversionBlockers',
  'detectMoment',
  'predictLTV',
  'predictIntent',
  'analyzeContent',
  // Messaging analysis tools — these analyze existing content, they don't generate regulated content
  'analyzePositioning',
  'analyzeGravitas',
  'analyzeBuyerObjections',
  'analyzeCompetitiveDifferentiation',
  'analyzeCrossChannelCoherence',
  'analyzeFearUrgency',
  'analyzeJourneyCoherence',
  'analyzePromiseProductAlignment',
  'checkCriticalAlignment',
  'checkCriticalObjectionGaps',
  'checkFeatureStartupLanguage',
  'checkGenericCopy',
  'checkSafeButForgettable',
  'compareMessaging',
  'comprehensiveGapAnalysis',
  'detectDrift',
  'getPreTractionMessaging',
  'getTrustRecommendations',
  'predictABTestWinner',
  'quickABCompare',
  'quickCompareHeadlines',
  'validateBusinessTruth',
  'clarifyIntent',
  'evaluateExperimentOutcome',
  // Baseline/experiment management tools — CRUD operations, not content generation
  'getLatestBaseline',
  'getBaselineHistory',
  'deactivateBaseline',
  'createExperimentFromPatch',
  'linkPatchToExperiment',
  'promoteWinner',
  'getPatchOutcome',
  'recordFeedback',
  'registerApprovedClaim',
  'calculateAttribution',
  'runAutoExpire',
  'getAuditById',
  'createAuditSchedule',
  'updateAuditSchedule',
  'deleteAuditSchedule',
  'runScheduledAuditNow',
  'listBreakGlass',
  'breakGlass',
  'breakGlassDrill',
  'runEscalation',
  'agentRuntimeValidateSite',
]);

// ============================================================================
// DEFAULT CONFIG
// ============================================================================

const DEFAULT_CONFIG: GateEnforcementConfig = {
  enabled: true,
  allowDegradedMode: true,
  gateTimeoutMs: 5000,
  logAllDecisions: true,
};

let _config: GateEnforcementConfig = { ...DEFAULT_CONFIG };
let _isDegraded = false;
let _degradedSince: number | null = null;
let _degradedReason: string | null = null;

// ============================================================================
// CORE ENFORCEMENT
// ============================================================================

/**
 * Pre-execution gate check for MCP tool calls.
 * 
 * This is the mechanical enforcement point that was missing.
 * Call this BEFORE executing any tool via the MCP handler.
 * 
 * Decision matrix:
 * - Exempt tool → passthrough (always allowed)
 * - Regulated surface → enforced (blocked without approval token)
 * - Advisory surface → advisory (allowed with warning)
 * - General surface → passthrough (allowed)
 * - Degraded mode → depends on surface (regulated = blocked, advisory/general = allowed with warning)
 */
export function enforceGate(
  toolName: string,
  args: Record<string, unknown>,
  options?: {
    surface?: Surface;
    approvalToken?: string;
    content?: string;
  }
): GateEnforcementResult {
  const gate = getFailClosedGate();
  const shortName = toolName.replace('gravito.', '');

  // Exempt tools bypass gate entirely
  if (EXEMPT_TOOLS.has(shortName)) {
    return {
      allowed: true,
      governance_mode: 'passthrough',
      requires_gate: false,
      advisory_only: false,
      surface: 'general',
      risk_level: 'low',
      reason: `Tool \"${shortName}\" is exempt from governance gate`,
      gravito_invocation_id: `exempt_${Date.now()}`,
    };
  }

  // Determine surface from: explicit option > args.surface_type > content detection > tool map > 'general'
  let surface: Surface = 'general';

  if (options?.surface) {
    // 1. Explicit option override (highest priority)
    surface = options.surface;
  } else {
    // 2. Check args.surface_type / args.surfaceType (explicit caller intent)
    const argSurface = (args.surface_type || args.surfaceType) as string | undefined;
    if (argSurface && isValidSurface(argSurface)) {
      surface = argSurface as Surface;
    } else {
      // 3. Content-based detection from args content fields
      const contentFields = ['content', 'text', 'message', 'body', 'prompt', 'input'];
      for (const field of contentFields) {
        if (typeof args[field] === 'string' && (args[field] as string).length > 10) {
          const detected = gate.detectSurface(args[field] as string);
          if (detected !== 'general') {
            surface = detected;
            break;
          }
        }
      }
      // 4. Also try options.content if provided
      if (surface === 'general' && options?.content) {
        surface = gate.detectSurface(options.content);
      }
      // 5. Fall back to tool map (only if it maps to a non-general surface)
      if (surface === 'general' && TOOL_SURFACE_MAP[shortName] && TOOL_SURFACE_MAP[shortName] !== 'general') {
        surface = TOOL_SURFACE_MAP[shortName];
      }
    }
  }

  const isRegulated = REGULATED_SURFACES.includes(surface);
  const isAdvisory = ADVISORY_SURFACES.includes(surface);
  const riskLevel = gate.assessRiskLevel(surface, shortName);

  // Check if system is in degraded mode
  if (_isDegraded) {
    if (isRegulated) {
      // Regulated surface in degraded mode = BLOCKED (fail-closed)
      return {
        allowed: false,
        governance_mode: 'degraded',
        requires_gate: true,
        advisory_only: false,
        surface,
        risk_level: riskLevel,
        reason: `System is in degraded mode (since ${new Date(_degradedSince || 0).toISOString()}). Regulated surface \"${surface}\" requires full governance — blocked until recovery.`,
        gravito_invocation_id: `degraded_${Date.now()}`,
        remediation: 'Wait for governance service recovery or contact system administrator.',
      };
    }
    // Advisory/general in degraded mode = allowed with warning
    return {
      allowed: true,
      governance_mode: 'degraded',
      requires_gate: isAdvisory,
      advisory_only: isAdvisory,
      surface,
      risk_level: riskLevel,
      reason: `System is in degraded mode. ${isAdvisory ? 'Advisory' : 'General'} surface \"${surface}\" allowed with reduced governance.`,
      gravito_invocation_id: `degraded_${Date.now()}`,
    };
  }

  // Run the gate check
  const gateDecision = gate.checkGate(shortName, options?.content || JSON.stringify(args), surface);

  // If gate blocks and caller has an approval token, validate it
  if (!gateDecision.allowed && options?.approvalToken) {
    const validation = gate.validateToken(options.approvalToken, shortName);
    if (validation.valid) {
      return {
        allowed: true,
        governance_mode: 'enforced',
        requires_gate: true,
        advisory_only: false,
        surface,
        risk_level: riskLevel,
        reason: `Approved via token ${options.approvalToken.substring(0, 12)}...`,
        gravito_invocation_id: validation.gravitoInvocationId,
        gate_decision: gateDecision,
      };
    }
  }

  // Gate blocked without valid token
  if (!gateDecision.allowed) {
    return {
      allowed: false,
      governance_mode: 'enforced',
      requires_gate: true,
      advisory_only: false,
      surface,
      risk_level: riskLevel,
      reason: gateDecision.reason,
      gravito_invocation_id: gateDecision.gravitoInvocationId,
      remediation: 'Call gravito.reviewContent first to obtain an approval token, then pass it as approval_token in the tool args.',
      gate_decision: gateDecision,
    };
  }

  // Gate allowed — determine mode
  const governanceMode: GovernanceMode = isRegulated ? 'enforced' : isAdvisory ? 'advisory' : 'passthrough';

  return {
    allowed: true,
    governance_mode: governanceMode,
    requires_gate: isRegulated,
    advisory_only: isAdvisory,
    surface,
    risk_level: riskLevel,
    reason: gateDecision.reason,
    gravito_invocation_id: gateDecision.gravitoInvocationId,
    gate_decision: gateDecision,
  };
}

// ============================================================================
// DEGRADED MODE MANAGEMENT
// ============================================================================

/**
 * Enter degraded mode when Gravito governance is unavailable.
 * In degraded mode:
 * - Regulated surfaces are BLOCKED (fail-closed)
 * - Advisory surfaces are ALLOWED with warning
 * - General surfaces are ALLOWED
 */
export function enterDegradedMode(reason: string): void {
  if (!_isDegraded) {
    _isDegraded = true;
    _degradedSince = Date.now();
    _degradedReason = reason;
    loadTelemetry()
      .then(() => _recordDegradedMode?.("system", "mcp", reason))
      .catch(() => {
        /* telemetry load is best-effort */
      });
  }
}

/**
 * Exit degraded mode when Gravito governance recovers.
 */
export function exitDegradedMode(): void {
  if (_isDegraded) {
    _isDegraded = false;
    _degradedSince = null;
    _degradedReason = null;
    loadTelemetry()
      .then(() => _recordDegradedRecovery?.())
      .catch(() => {
        /* telemetry load is best-effort */
      });
  }
}

/**
 * Get current degraded mode status.
 */
export function getDegradedStatus(): {
  isDegraded: boolean;
  since: number | null;
  reason: string | null;
  durationMs: number | null;
} {
  return {
    isDegraded: _isDegraded,
    since: _degradedSince,
    reason: _degradedReason,
    durationMs: _isDegraded && _degradedSince ? Date.now() - _degradedSince : null,
  };
}

// ============================================================================
// RESPONSE ENRICHMENT
// ============================================================================

/**
 * Build the governance envelope to attach to every MCP response.
 * This makes the gate decision explicit and machine-readable.
 */
export function buildGovernanceEnvelope(enforcement: GateEnforcementResult): Record<string, unknown> {
  return {
    _governance: {
      mode: enforcement.governance_mode,
      requires_gate: enforcement.requires_gate,
      advisory_only: enforcement.advisory_only,
      surface: enforcement.surface,
      risk_level: enforcement.risk_level,
      gravito_invocation_id: enforcement.gravito_invocation_id,
      ...(enforcement.remediation ? { remediation: enforcement.remediation } : {}),
      ...(enforcement.governance_mode === 'degraded' ? {
        degraded: getDegradedStatus(),
      } : {}),
    },
  };
}

// ============================================================================
// CONFIG
// ============================================================================

export function updateGateConfig(updates: Partial<GateEnforcementConfig>): void {
  _config = { ..._config, ...updates };
}

export function getGateConfig(): GateEnforcementConfig {
  return { ..._config };
}

// ============================================================================
// HELPERS
// ============================================================================

function isValidSurface(s: string): boolean {
  const allSurfaces: readonly Surface[] = [...REGULATED_SURFACES, ...ADVISORY_SURFACES, 'general'];
  return allSurfaces.includes(s as Surface);
}

/**
 * Reset state (for testing)
 */
export function _resetForTesting(): void {
  _config = { ...DEFAULT_CONFIG };
  _isDegraded = false;
  _degradedSince = null;
  _degradedReason = null;
}

