const ts = require('/home/user/exp0006-arm/node_modules/typescript');
const path = require('path');

const projectDir = '/home/user/exp0006-arm';
const configPath = path.join(projectDir, process.argv[2] || 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, projectDir);
parsed.options.noEmit = true;

const program = ts.createProgram(parsed.fileNames, parsed.options);
const diags = ts.getPreEmitDiagnostics(program);
const filter = process.argv[3];
let count = 0;
const byFile = new Map();
for (const d of diags) {
  const file = d.file ? path.relative(projectDir, d.file.fileName) : '<global>';
  byFile.set(file, (byFile.get(file) || 0) + 1);
  count++;
}
console.log('TOTAL ERRORS:', count);
console.log('--- per file ---');
for (const [f, c] of [...byFile.entries()].sort((a, b) => b[1] - a[1])) {
  console.log(c, f);
}
if (filter) {
  console.log('--- details for', filter, '---');
  for (const d of diags) {
    if (!d.file) continue;
    const rel = path.relative(projectDir, d.file.fileName);
    if (!rel.includes(filter)) continue;
    const { line, character } = d.file.getLineAndCharacterOfPosition(d.start);
    console.log(`${rel}(${line + 1},${character + 1}): error TS${d.code}: ${ts.flattenDiagnosticMessageText(d.messageText, '\n  ')}`);
  }
}

