const governanceTools: Record<string, ToolHandler> = {
  reviewContent: async (args) => {
    const server = getGravitoMCPServer();
    // Normalize common parameter mismatches from MCP clients
    const normalized = { ...args } as Record<string, unknown>;
    // surface → surface_type
    if (normalized.surface && !normalized.surface_type) {
      normalized.surface_type = normalized.surface;
      delete normalized.surface;
    }
    // Default surface_type to 'marketing' if missing
    if (!normalized.surface_type) normalized.surface_type = 'marketing';
    // Default artifact_type to 'web_copy' if missing (valid: email|message|web_copy|doc|ad_copy)
    if (!normalized.artifact_type) normalized.artifact_type = 'web_copy';
    // Default to 'quick' mode for MCP calls — fast deterministic checks only.
    // Users can explicitly pass mode: 'release_gate' for full analysis.
    if (!normalized.mode) normalized.mode = 'quick';
    const result = await server.reviewContent(normalized as any);
    // Generate an approval_token when content passes review (not blocked)
    // This token can be passed to downstream tools to unlock gated operations
    if (result && typeof result === 'object' && !result.block_release) {
      try {
        const { getFailClosedGate } = await import('./fail-closed-gate');
        const gate = getFailClosedGate();
        const token = gate.createApprovalToken(
          (normalized.surface_type as string) || 'general',
          'reviewContent',
          true,
          [],
          (normalized.policy_preset as string) || 'default',
          false
        );
        (result as Record<string, unknown>).approval_token = token.tokenId;
      } catch (tokenErr) {
        // Non-fatal: proceed without token
      }
    }
    return mcpText(result);
  },

