const enhancedToolHandlers: Record<string, ToolHandler> = {
  reviewArtifact: async (args) => mcpText(await enhancedReviewArtifact(args as Record<string, unknown>)),
  surfaceIntelTrackEvent: async (args) => mcpText(await enhancedTrackEvent(args as Record<string, unknown>)),
  surfaceIntelGetConversionBlockers: async (args) => mcpText(await enhancedGetConversionBlockers(args as Record<string, unknown>)),
  detectMoment: async (args) => mcpText(await enhancedDetectMoment(args as Record<string, unknown>)),
  analyzeContent: async (args) => mcpText(await enhancedAnalyzeContent(args as Record<string, unknown>)),
};

const TOOL_DISPATCH: Record<string, ToolHandler> = {
  ...governanceTools,
  ...complianceTools,
  ...outboundTools,
  ...financeTools,
  ...agentRuntimeTools,
  ...creativeTools,
  ...workflowTools,
  ...breakGlassTools,
