    // (`_def.type` there is the "array" discriminant string, not a schema).
    const arrayDef = (schema as z.ZodType<unknown> & { _def: { element?: unknown; type?: unknown } })._def;
    const element = arrayDef.element ?? arrayDef.type;
    return { type: 'array', items: zodToJsonSchema(element as z.ZodType<unknown>), description };
  }
  if (schema instanceof z.ZodEnum) {
    // zod v3 exposes `_def.values` (a string array); zod v4 exposes `_def.entries` (a record).
    const enumDef = (schema as z.ZodType<unknown> & { _def: { values?: unknown; entries?: Record<string, unknown> } })._def;
    return { type: 'string', enum: enumDef.values ?? Object.keys(enumDef.entries ?? {}), description };
  }
  if (schema instanceof z.ZodDefault) {
    const inner = zodToJsonSchema((schema as z.ZodDefault<ZodTypeAny>)._def.innerType);
    try {
      const defaultVal = (schema as z.ZodType<unknown> & { _def: { defaultValue: unknown } })._def.defaultValue;
      inner.default = typeof defaultVal === 'function' ? defaultVal() : defaultVal;
    } catch { /* ignore */ }
    return inner;
  }
  if (schema instanceof z.ZodOptional) {
    return zodToJsonSchema((schema as z.ZodOptional<ZodTypeAny>)._def.innerType);
